export function TopologyPane({ selectedTimeSec = null, filterQuery = "", streamDisplayNames = new Map(), dashboard = false, focusStreamKey = null, focusFlowKey = null, onSelectStream, onSelectFlow, onSelectTime }: TopologyPaneProps) {
