export type EventLogItem = {
  id: string;
  time: number;
  type: string;
  level: "info" | "warn" | "error";
  scope: "system" | "stream" | "flow";
  proto?: string;
  interfaceId?: number;
  streamKey?: string;
  flowKey?: string;
  targetLabel?: string;
  message: string;
  detail?: unknown;
};

export type TopologyAlertSummary = {
  state?: string;
  severity?: string;
  count?: number;
  alerts?: unknown[];
};

export type TopologyNode = {
  id: string;
  type: string;
