  font-size: var(--font-size-xs);
  padding: 3px 5px;
}

.topology-flow .react-flow__edge.topology-rf-edge .react-flow__edge-path {
  stroke-opacity: .68;
  transition: stroke-width .18s ease, stroke-opacity .18s ease;
}

.topology-flow .react-flow__edge.topology-rf-edge.stale .react-flow__edge-path {
  stroke-dasharray: 6 5;
  stroke-opacity: .4;
}

.topology-rf-node-stale,
.topology-schema-node-stale {
  opacity: .52;
}

.topology-schema-node-stale {
  border-color: color-mix(in srgb, var(--muted) 65%, var(--line));
