      if (lastFitRequest.current === fitRequest) return;
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(() => {
        if (mapCard.clientWidth > 0 && mapCard.clientHeight > 0) {
          if (diagnostic) console.info("[STM_DIAG] topology client fit", { width: mapCard.clientWidth, height: mapCard.clientHeight });
