  const [selectedRelationId, setSelectedRelationId] = useState<string | null>(null);
  const [selectedEdgeIds, setSelectedEdgeIds] = useState<Set<string>>(new Set());
  const [selectedEndpointKeys, setSelectedEndpointKeys] = useState<Set<string>>(new Set());
  const [flowInstance, setFlowInstance] = useState<ReactFlowInstance<Node<TopologyNodeData>, TopologyFlowEdge> | null>(null);
  const [activeOnly, setActiveOnly] = useState(false);
  const [frozenSnapshot, setFrozenSnapshot] = useState<TopologySnapshot | null>(null);
  const [positionVersion, setPositionVersion] = useState(0);
  const [fitRequest, setFitRequest] = useState(0);
  const [mapMode, setMapMode] = useState<TopologyMapMode>("service");
  const [relationFlows, setRelationFlows] = useState<TopologyRelationFlowsResponse | null>(null);
  const [includeStaleFlows, setIncludeStaleFlows] = useState(false);
  const [flowError, setFlowError] = useState<string | null>(null);
  const [layoutMode, setLayoutMode] = useState<TopologyLayoutMode>(readTopologyLayoutMode);
  const mapCardRef = useRef<HTMLDivElement | null>(null);
  const manualNodePositions = useRef(new Map<string, XYPosition>());
  const automaticNodePositions = useRef(new Map<TopologyLayoutMode, Map<string, XYPosition>>());
  const lastFitRequest = useRef<number>();
  const previousFocusKeyRef = useRef<string | null>(null);
  const diagnostic = typeof window !== "undefined" && window.localStorage.getItem("stm-diagnostic") === "1";

  useEffect(() => {
    let cancelled = false;
    const load = async () => {
      if (selectedTimeSec !== null) setLoading(true);
      try {
        const next = await getTopology(selectedTimeSec ?? undefined);
        if (cancelled) return;
        setSnapshot(next);
        setError(null);
