function renderedServiceHandle(node: ReturnType<typeof buildTopologyGraph>["nodes"][number] | undefined, serviceKey?: string) {
  if (!node || node.services.length === 0) return serviceKey;
  if (serviceKey && node.services.slice(0, MAX_VISIBLE_SERVICES).some((service) => service.key === serviceKey)) return serviceKey;
  return node.services.length > MAX_VISIBLE_SERVICES ? OVERFLOW_SERVICE_KEY : serviceKey;
}

function matchesServiceSelection(node: ReturnType<typeof buildTopologyGraph>["nodes"][number] | undefined, edgeNodeId: string, edgeServiceKey: string | undefined, selectedNodeId: string, selectedServiceKey: string) {
  if (edgeNodeId !== selectedNodeId) return false;
  if (selectedServiceKey !== OVERFLOW_SERVICE_KEY) return edgeServiceKey === selectedServiceKey;
  return !node?.services.slice(0, MAX_VISIBLE_SERVICES).some((service) => service.key === edgeServiceKey);
}

function naturalBezierPath(sourceX: number, sourceY: number, sourcePosition: Position, targetX: number, targetY: number, targetPosition: Position): [string, number, number] {
  const sourceDirection = horizontalDirection(sourcePosition, 1);
  const targetDirection = horizontalDirection(targetPosition, -1);
  const stubLength = 10;
  const controlLength = 40;
  const startX = sourceX + sourceDirection * stubLength;
  const endX = targetX + targetDirection * stubLength;
  const firstControlX = startX + sourceDirection * controlLength;
  const firstControlY = sourceY;
  const secondControlX = endX + targetDirection * controlLength;
  const secondControlY = targetY;
  return [
    `M${sourceX},${sourceY} L${startX},${sourceY} C${firstControlX},${firstControlY} ${secondControlX},${secondControlY} ${endX},${targetY} L${targetX},${targetY}`,
    (startX + endX) / 2,
    (sourceY + targetY) / 2
  ];
}

function horizontalDirection(position: Position, fallback: -1 | 1): -1 | 1 {
  if (position === Position.Left) return -1;
  if (position === Position.Right) return 1;
  return fallback;
}

