import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { Background, BaseEdge, Controls, EdgeLabelRenderer, Handle, MarkerType, MiniMap, Position, ReactFlow, useNodesInitialized, useReactFlow, useUpdateNodeInternals, type Edge, type EdgeProps, type EdgeTypes, type Node, type NodeProps, type XYPosition } from "@xyflow/react";
import type { TopologyRelationFlowsResponse, TopologySnapshot } from "../types/api";
import { getTopology, getTopologyRelationFlows } from "../api/client";
import { formatNumber } from "./format";
import { buildTopologyGraph } from "./topologyModel";
import type { TopologyGraphEdge, TopologyLayoutMode, TopologyService } from "./topologyModel";
import { matchesSearch } from "./search";
import { Icon } from "./ui/Icon";
import { SearchInput } from "./ui/SearchInput";

type TopologyPaneProps = {
  selectedTimeSec?: number | null;
  /** The application-wide Updated timestamp, used to avoid duplicating the same time in this pane. */
  updatedAt?: number | null;
  filterQuery?: string;
  streamDisplayNames?: ReadonlyMap<string, string>;
  dashboard?: boolean;
  focusStreamKey?: string | null;
  focusFlowKey?: string | null;
  onSelectStream?: (streamKey: string) => void;
  onSelectFlow?: (streamKey: string, flowKey: string) => void;
  onSelectTime?: (timeSec: number) => void;
  /** Opens the standalone Inspector after this pane has selected the edge target. */
  onOpenInspector?: () => void;
};

type TopologyNodeData = {
  label: string;
  host: string;
  nodeId: string;
  services: TopologyService[];
  hiddenServiceCount: number;
  selectedEndpointKeys: Set<string>;
  onSelectEndpoint: (nodeId: string, serviceKey: string) => void;
  alert?: boolean;
  state: "active" | "stale";
};

type TopologyEdgeData = {
  edge: TopologyGraphEdge;
  label: string;
  selected: boolean;
  searchMatch: boolean;
  searchDimmed: boolean;
};

type TopologySearchMatches = {
  active: boolean;
  nodeIds: Set<string>;
  edgeIds: Set<string>;
};

type TopologyFlowEdge = Edge<TopologyEdgeData>;
type TopologyMapMode = "service" | "flow";
const MAX_VISIBLE_SERVICES = 4;
const OVERFLOW_SERVICE_KEY = "__other_flows__";
const TOPOLOGY_LAYOUT_STORAGE_KEY = "stm-topology-layout-mode";

const topologyEdgeTypes: EdgeTypes = {
  topology: TopologyParallelEdge
};

const topologyNodeTypes = {
  topologySchema: TopologySchemaNode
};

export function TopologyPane({ selectedTimeSec = null, updatedAt = null, filterQuery = "", streamDisplayNames = new Map(), dashboard = false, focusStreamKey = null, focusFlowKey = null, onSelectStream, onSelectFlow, onSelectTime, onOpenInspector }: TopologyPaneProps) {
  const [snapshot, setSnapshot] = useState<TopologySnapshot | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [reloadVersion, setReloadVersion] = useState(0);
  const [selectedEdgeId, setSelectedEdgeId] = useState<string | null>(null);
  const [selectedRelationId, setSelectedRelationId] = useState<string | null>(null);
  const [selectedEdgeIds, setSelectedEdgeIds] = useState<Set<string>>(new Set());
  const [selectedEndpointKeys, setSelectedEndpointKeys] = useState<Set<string>>(new Set());
  const [topologyReady, setTopologyReady] = useState(false);
  const [activeOnly, setActiveOnly] = useState(false);
  const [frozenSnapshot, setFrozenSnapshot] = useState<TopologySnapshot | null>(null);
  const [positionVersion, setPositionVersion] = useState(0);
  const [fitRequest, setFitRequest] = useState(0);
  const [mapMode, setMapMode] = useState<TopologyMapMode>("service");
  const [relationFlows, setRelationFlows] = useState<TopologyRelationFlowsResponse | null>(null);
  const [includeStaleFlows, setIncludeStaleFlows] = useState(false);
  const [flowError, setFlowError] = useState<string | null>(null);
  const [layoutMode, setLayoutMode] = useState<TopologyLayoutMode>(readTopologyLayoutMode);
  const [searchQuery, setSearchQuery] = useState(filterQuery);
  const mapCardRef = useRef<HTMLDivElement | null>(null);
  const manualNodePositions = useRef(new Map<string, XYPosition>());
  const automaticNodePositions = useRef(new Map<TopologyLayoutMode, Map<string, XYPosition>>());
  const previousFocusKeyRef = useRef<string | null>(null);
  const diagnostic = typeof window !== "undefined" && window.localStorage.getItem("stm-diagnostic") === "1";

  useEffect(() => setSearchQuery(filterQuery), [filterQuery]);

  useEffect(() => {
    let cancelled = false;
    let timer: number | undefined;
    const load = async () => {
      if (selectedTimeSec !== null) setLoading(true);
      try {
        const next = await getTopology(selectedTimeSec ?? undefined);
        if (cancelled) return;
        setSnapshot(next);
        setError(null);
      } catch (caught) {
        if (cancelled) return;
        setError(caught instanceof Error ? caught.message : "failed to load topology");
      } finally {
        if (cancelled) return;
        setLoading(false);
        if (selectedTimeSec === null) timer = window.setTimeout(() => void load(), 2000);
      }
    };
    void load();
    return () => {
      cancelled = true;
      if (timer !== undefined) window.clearTimeout(timer);
    };
  }, [reloadVersion, selectedTimeSec]);

  useEffect(() => {
    try { window.localStorage.setItem(TOPOLOGY_LAYOUT_STORAGE_KEY, layoutMode); } catch { /* Storage is optional. */ }
    setFitRequest((value) => value + 1);
  }, [layoutMode]);

  useEffect(() => {
    if (selectedTimeSec === null) return;
    setMapMode("service");
    setRelationFlows(null);
    setFlowError(null);
    setActiveOnly(false);
    setSelectedRelationId(null);
  }, [selectedTimeSec]);

  useEffect(() => {
    if (mapMode !== "flow" || !selectedRelationId || selectedTimeSec !== null) return;
    let cancelled = false;
    void getTopologyRelationFlows(selectedRelationId, includeStaleFlows)
      .then((next) => { if (!cancelled) { setRelationFlows(next); setFlowError(null); } })
      .catch((caught) => { if (!cancelled) setFlowError(caught instanceof Error ? caught.message : "failed to load flows"); });
    return () => { cancelled = true; };
  }, [includeStaleFlows, mapMode, selectedRelationId, selectedTimeSec]);

  const displayedSnapshot = frozenSnapshot ?? snapshot;
  const historicalRaw = selectedTimeSec !== null;
  const effectiveMapMode: TopologyMapMode = mapMode === "flow" || historicalRaw ? "flow" : "service";
  const mapSnapshot = !historicalRaw && mapMode === "flow" && relationFlows ? flowMapSnapshot(relationFlows) : displayedSnapshot;
  const effectiveActiveOnly = !historicalRaw && mapMode === "service" && activeOnly;
  const visibleSnapshot = useMemo(() => effectiveActiveOnly && mapSnapshot ? {
    ...mapSnapshot,
    nodes: mapSnapshot.nodes.filter((node) => node.state !== "stale"),
    edges: mapSnapshot.edges.filter((edge) => edge.state !== "stale")
  } : mapSnapshot, [effectiveActiveOnly, mapSnapshot]);
  const automaticPositions = automaticPositionsFor(automaticNodePositions.current, layoutMode);
  const sourceGraph = useMemo(() => positionGraphNodes(buildTopologyGraph(visibleSnapshot, layoutMode), manualNodePositions.current, automaticPositions), [automaticPositions, layoutMode, positionVersion, visibleSnapshot]);
  /* Search changes emphasis only: keeping all elements preserves the map's stable layout and context. */
  const graph = sourceGraph;
  const searchMatches = useMemo(() => findTopologySearchMatches(graph, searchQuery, streamDisplayNames), [graph, searchQuery, streamDisplayNames]);
  const focusEdgeIds = useMemo(() => {
    if (!focusStreamKey) return new Set<string>();
    const streamMatches = graph.edges.filter((edge) => edge.identity?.stream_key === focusStreamKey);
    if (!focusFlowKey) return new Set(streamMatches.map((edge) => edge.id));
    const flowMatches = streamMatches.filter((edge) => edge.identity?.flow_key === focusFlowKey);
    /* Live service maps aggregate flows. Prefer an exact flow match, and otherwise retain the owning stream relation. */
    return new Set((flowMatches.length > 0 ? flowMatches : streamMatches).map((edge) => edge.id));
  }, [focusFlowKey, focusStreamKey, graph.edges]);
  const highlightedEdgeIds = useMemo(() => new Set([...selectedEdgeIds, ...focusEdgeIds]), [focusEdgeIds, selectedEdgeIds]);
  const focusEndpointKeys = useMemo(() => selectedEndpointKeysFor(graph.edges, focusEdgeIds), [focusEdgeIds, graph.edges]);
  const highlightedEndpointKeys = useMemo(() => new Set([...selectedEndpointKeys, ...focusEndpointKeys]), [focusEndpointKeys, selectedEndpointKeys]);
  const selectedNodeIds = useMemo(() => selectedConnectedNodeIds(graph.edges, highlightedEdgeIds), [graph.edges, highlightedEdgeIds]);
  const clearEdgeSelection = () => {
    setSelectedEdgeId(null);
    setSelectedRelationId(null);
    setSelectedEdgeIds(new Set());
    setSelectedEndpointKeys(new Set());
  };
  const focusKey = focusStreamKey ? focusStreamKey + ":" + (focusFlowKey ?? "") : null;
  useEffect(() => {
    if (previousFocusKeyRef.current === focusKey) return;
    previousFocusKeyRef.current = focusKey;
    clearEdgeSelection();
  }, [focusKey]);
  const handleEndpointSelect = (nodeId: string, serviceKey: string) => {
    const matchingEdges = graph.edges.filter((edge) =>
      matchesServiceSelection(graph.nodeById.get(edge.srcHostId), edge.srcHostId, edge.srcServiceKey, nodeId, serviceKey) ||
      matchesServiceSelection(graph.nodeById.get(edge.dstHostId), edge.dstHostId, edge.dstServiceKey, nodeId, serviceKey)
    );
    const nextEdgeIds = new Set(matchingEdges.map((edge) => edge.id));
    const nextEndpointKeys = new Set<string>();
    for (const edge of matchingEdges) {
      nextEndpointKeys.add(endpointSelectionKey(edge.srcHostId, edge.srcServiceKey));
      nextEndpointKeys.add(endpointSelectionKey(edge.dstHostId, edge.dstServiceKey));
    }
    setSelectedEdgeId(matchingEdges[0]?.id ?? null);
    setSelectedEdgeIds(nextEdgeIds);
    setSelectedEndpointKeys(nextEndpointKeys);
    const selected = matchingEdges[0];
    if (selected) handleEdgeSelect(selected);
  };
  const flowModel = useMemo(() => buildReactFlowModel(graph.nodes, graph.edges, highlightedEdgeIds, selectedNodeIds, highlightedEndpointKeys, searchMatches, handleEndpointSelect), [graph.nodes, graph.edges, highlightedEdgeIds, selectedNodeIds, highlightedEndpointKeys, searchMatches]);
  const flowNodeIds = useMemo(() => flowModel.nodes.map((node) => node.id), [flowModel.nodes]);
  const topologyRenderKey = useMemo(() => topologyModelRenderKey(flowModel), [flowModel]);
  const selectedEdge = selectedEdgeId ? graph.edges.find((edge) => edge.id === selectedEdgeId) : undefined;
  const focusedTargetMissing = dashboard && Boolean(focusStreamKey) && graph.edges.length > 0 && focusEdgeIds.size === 0;

  useEffect(() => {
    setTopologyReady(flowModel.nodes.length === 0);
  }, [flowModel.nodes.length, topologyRenderKey]);

  const handleTopologyReady = useCallback((readyKey: string) => {
    if (readyKey === topologyRenderKey) setTopologyReady(true);
  }, [topologyRenderKey]);

  useEffect(() => {
    if (!dashboard || !selectedEdgeId) return;
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") clearEdgeSelection();
    };
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [dashboard, selectedEdgeId]);

  useEffect(() => {
    for (const node of sourceGraph.nodes) {
      if (!manualNodePositions.current.has(node.id) && !automaticPositions.has(node.id)) automaticPositions.set(node.id, { x: node.x, y: node.y });
    }
  }, [automaticPositions, sourceGraph.nodes]);

  useEffect(() => {
    if (!diagnostic) return;
    console.info("[STM_DIAG] topology client render", { selectedTimeSec, snapshotTime: snapshot?.time, nodes: graph.nodes.length, edges: graph.edges.length, mapWidth: mapCardRef.current?.clientWidth ?? 0, mapHeight: mapCardRef.current?.clientHeight ?? 0 });
  }, [diagnostic, selectedTimeSec, snapshot?.time, graph.nodes.length, graph.edges.length]);

  const handleEdgeNavigation = (edge: TopologyGraphEdge) => {
    const streamKey = edge.identity?.stream_key;
    const flowKey = edge.identity?.flow_key;
    if (diagnostic) console.info("[STM_DIAG] topology inspect", {
      edgeId: edge.id,
      streamKey,
      flowKey,
      selectedTimeSec,
      snapshotTime: snapshot?.time,
      displayedSnapshotTime: mapSnapshot?.time
    });
    if (streamKey && flowKey) onSelectFlow?.(streamKey, flowKey);
    else if (streamKey) onSelectStream?.(streamKey);
    if (!dashboard && snapshot?.time) onSelectTime?.(snapshot.time);
  };

  const handleEdgeSelect = (edge: TopologyGraphEdge) => {
    if (mapMode === "service" && selectedTimeSec === null) setSelectedRelationId(edge.id);
    setSelectedEdgeId(edge.id);
    setSelectedEdgeIds(new Set([edge.id]));
    setSelectedEndpointKeys(new Set([
      endpointSelectionKey(edge.srcHostId, edge.srcServiceKey),
      endpointSelectionKey(edge.dstHostId, edge.dstServiceKey)
    ]));
  };

  const openFlowMap = () => {
    if (!selectedEdge || !selectedRelationId || selectedTimeSec !== null) return;
    setMapMode("flow");
    setRelationFlows(null);
    setFlowError(null);
    setSelectedEdgeId(null);
    setSelectedEdgeIds(new Set());
    setSelectedEndpointKeys(new Set());
  };

  const closeFlowMap = () => {
    setMapMode("service");
    setRelationFlows(null);
    setFlowError(null);
    setActiveOnly(false);
  };
  const retryTopology = () => setReloadVersion((value) => value + 1);
  const title = historicalRaw ? "Topology / Historical flow map" : effectiveMapMode === "flow" ? "Topology / Flow map" : "Topology / Service map";
  const snapshotTimeIsGlobal = mapSnapshot !== null && updatedAt !== null && Math.abs(mapSnapshot.time - updatedAt) < 1;

  return (
    <section className="topology-pane">
      <header className="pane-header topology-header">
        <div className="topology-header-main">
          <div className="pane-header-title-with-icon"><Icon className="pane-header-icon" name="topology" size={14} /><h2>{title}</h2></div>
          <span className="topology-header-meta">
            {mapSnapshot
              ? <>{graph.nodes.length} hosts / {graph.edges.length} {effectiveMapMode === "flow" ? "flows" : "relations"}{!snapshotTimeIsGlobal && <> / {formatTime(mapSnapshot.time)}</>}{frozenSnapshot && <> / frozen</>}</>
              : "Waiting for topology snapshot"}
          </span>
        </div>
        <div className="topology-badges">
          {!dashboard && <SearchInput className="topology-search" value={searchQuery} onChange={setSearchQuery} placeholder="Highlight hosts, services, flows…" label="Topology search" />}
          <span>{alertCount(mapSnapshot)} alerts</span>
          <span>{activeEdgeCount(mapSnapshot)} active {effectiveMapMode === "flow" ? "flows" : "relations"}</span>
          <span title="Edge width uses a logarithmic bitrate scale">Traffic = line width</span>
          <label className="topology-layout-mode"><span>Layout</span><select value={layoutMode} onChange={(event) => setLayoutMode(event.target.value as TopologyLayoutMode)}><option value="balanced">Balanced</option><option value="vertical">Vertical</option><option value="horizontal">Horizontal</option></select></label>
          {mapMode === "flow" ? <><button type="button" aria-pressed={includeStaleFlows} onClick={() => setIncludeStaleFlows((value) => !value)}>{includeStaleFlows ? "Hide stale" : "Include stale"}</button><button type="button" onClick={closeFlowMap}>Back to service map</button></> : <button type="button" aria-pressed={activeOnly} onClick={() => setActiveOnly((value) => !value)}>{activeOnly ? "Show stale" : "Active only"}</button>}
          <button type="button" aria-pressed={Boolean(frozenSnapshot)} onClick={() => setFrozenSnapshot((value) => value ? null : cloneSnapshot(snapshot))}>{frozenSnapshot ? "Unfreeze" : "Freeze"}</button>
          <button type="button" onClick={() => setFitRequest((value) => value + 1)}>Fit</button>
        </div>
      </header>
      <div className="topology-body">
        <div ref={mapCardRef} className="topology-map-card">
          {loading && selectedTimeSec !== null && <div className="dashboard-cell-loading-overlay" role="status" aria-live="polite"><div className="dashboard-cell-loading-dialog"><div className="timeline-loading-spinner" /><span>Loading topology…</span></div></div>}
          {error && snapshot && <div className="topology-refresh-notice" role="status">{error}<button type="button" onClick={retryTopology}>Retry</button></div>}
          {(error && !snapshot) || flowError ? (
            <div className="topology-empty">{flowError ?? error}{error && !flowError && <button type="button" onClick={retryTopology}>Retry</button>}</div>
          ) : graph.nodes.length === 0 ? (
            <div className="topology-empty">No topology data</div>
          ) : (
            <ReactFlow<Node<TopologyNodeData>, TopologyFlowEdge>
              className="topology-flow"
              style={{ width: "100%", height: "100%" }}
              nodes={flowModel.nodes}
              edges={flowModel.edges}
              minZoom={0.2}
              maxZoom={4}
              nodesDraggable
              nodesConnectable={false}
              elementsSelectable
              nodeTypes={topologyNodeTypes}
              edgeTypes={topologyEdgeTypes}
              elevateEdgesOnSelect
              proOptions={{ hideAttribution: true }}
              onInit={() => {
                if (diagnostic) console.info("[STM_DIAG] topology client init", { width: mapCardRef.current?.clientWidth ?? 0, height: mapCardRef.current?.clientHeight ?? 0 });
              }}
              onEdgeClick={(_, edge) => { if (edge.data?.edge) handleEdgeSelect(edge.data.edge); }}
              onEdgeDoubleClick={(_, edge) => { if (edge.data?.edge) handleEdgeNavigation(edge.data.edge); }}
              onPaneClick={clearEdgeSelection}
              onNodeClick={(_, node) => {
                const firstEdge = graph.edges.find((edge) => edge.srcHostId === node.id || edge.dstHostId === node.id);
                if (firstEdge) handleEdgeSelect(firstEdge);
              }}
              onNodeDragStop={(_, node) => {
                manualNodePositions.current.set(node.id, { x: node.position.x, y: node.position.y });
                setPositionVersion((value) => value + 1);
              }}
            >
              <TopologyRenderLifecycle
                nodeIds={flowNodeIds}
                renderKey={topologyRenderKey}
                fitRequest={fitRequest}
                mapCardRef={mapCardRef}
                diagnostic={diagnostic}
                onReady={handleTopologyReady}
              />
              <Background gap={28} size={1} />
              <MiniMap pannable zoomable nodeStrokeWidth={3} position={dashboard ? "top-right" : "bottom-right"} />
              <Controls showInteractive={false} />
            </ReactFlow>
          )}
          {!topologyReady && graph.nodes.length > 0 && <div className="dashboard-cell-loading-overlay" role="status" aria-live="polite"><div className="dashboard-cell-loading-dialog"><div className="timeline-loading-spinner" /><span>Preparing topology…</span></div></div>}
          {dashboard && focusedTargetMissing && <div className="dashboard-topology-focus-status" role="status">Focused target is not present at this time</div>}
          {dashboard && selectedEdge && <DashboardEdgeSelectionPanel edge={selectedEdge} onClear={clearEdgeSelection} onInspect={() => { handleEdgeNavigation(selectedEdge); clearEdgeSelection(); }} />}
        </div>
        <aside className="topology-side-card">
          <h3>{effectiveMapMode === "flow" ? "Flow drill-down" : "Selected service relation"}</h3>
          {selectedEdge ? <EdgeSummary edge={selectedEdge} onViewFlows={!historicalRaw && mapMode === "service" ? openFlowMap : undefined} onOpenInspector={!dashboard && onOpenInspector ? () => { handleEdgeNavigation(selectedEdge); onOpenInspector(); } : undefined} /> : <p className="topology-muted">No edge selected</p>}
        </aside>
      </div>
    </section>
  );
}

type TopologyRenderLifecycleProps = {
  nodeIds: string[];
  renderKey: string;
  fitRequest: number;
  mapCardRef: { current: HTMLDivElement | null };
  diagnostic: boolean;
  onReady: (renderKey: string) => void;
};

function TopologyRenderLifecycle({ nodeIds, renderKey, fitRequest, mapCardRef, diagnostic, onReady }: TopologyRenderLifecycleProps) {
  const reactFlow = useReactFlow<Node<TopologyNodeData>, TopologyFlowEdge>();
  const nodesInitialized = useNodesInitialized();
  const updateNodeInternals = useUpdateNodeInternals();
  const completedRequest = useRef<string | null>(null);
  for (const edge of edges) {
    if (!edgeIds.has(edge.id)) continue;
    keys.add(endpointSelectionKey(edge.srcHostId, edge.srcServiceKey));
    keys.add(endpointSelectionKey(edge.dstHostId, edge.dstServiceKey));
  }
  return keys;
}

function endpointSelectionKey(nodeId: string, serviceKey?: string) {
  return `${nodeId}|${serviceKey ?? "host"}`;
}

function topologyHandleId(kind: "source" | "target", key?: string) {
  return `${kind}:${encodeURIComponent(key ?? "host")}`;
}

function portPairLabel(edge: TopologyGraphEdge) {
  const flowEndpoint = recordValue(edge.flow_endpoint);
  const src = endpointParts(endpointString(flowEndpoint?.src) ?? endpointString(edge.endpoint?.src) ?? edge.src);
  const dst = endpointParts(endpointString(flowEndpoint?.dst) ?? endpointString(edge.endpoint?.dst) ?? edge.dst);
  const pair = `${src.port ?? "host"}:${dst.port ?? "host"}`;
  const proto = edge.proto ?? edge.transport;
  return proto ? `${pair} / ${proto}` : pair;
}

function endpointString(value: unknown) {
  return typeof value === "string" && value.length > 0 ? value : undefined;
}

function endpointParts(value: string) {
  const noTransport = value.replace(/\/[A-Za-z0-9_-]+$/, "");
  const ipv6 = noTransport.match(/^\[([^\]]+)\]:(\d+)$/);
  if (ipv6) return { host: ipv6[1], port: Number(ipv6[2]) };
  const ipv4 = noTransport.match(/^(.+):(\d+)$/);
  if (ipv4 && !ipv4[1].includes(":")) return { host: ipv4[1], port: Number(ipv4[2]) };
  return { host: noTransport };
}

function EdgeSummary({ edge, onViewFlows, onOpenInspector }: { edge: TopologyGraphEdge; onViewFlows?: () => void; onOpenInspector?: () => void }) {
  const metrics = edge.metrics ?? {};
  const flowEndpoint = recordValue(edge.flow_endpoint);
  const summary = edge.flow_summary;
  return (
    <div className="topology-edge-summary">
      <strong>{edge.proto ?? edge.transport ?? "edge"}</strong>
      <span>{endpointString(flowEndpoint?.src) ?? edge.src} → {endpointString(flowEndpoint?.dst) ?? edge.dst}</span>
      <dl>
        <dt>Ports</dt><dd>{portPairLabel(edge)}</dd>
        <dt>State</dt><dd>{edge.state ?? "unknown"}</dd>
        {edge.state === "stale" && typeof edge.lost_at === "number" && <><dt>Lost</dt><dd>{formatTime(edge.lost_at)}</dd></>}
        <dt>Last seen</dt><dd>{typeof edge.last_seen === "number" ? formatTime(edge.last_seen) : "-"}</dd>
        <dt>Scope</dt><dd>{edge.scopeLabel}</dd>
        <dt>Role</dt><dd>{edge.role ?? "-"}</dd>
        <dt>Bitrate</dt><dd>{metricValue(metrics.bitrate_bps, "bps")}</dd>
        <dt>Packets</dt><dd>{metricValue(metrics.packet_rate_pps, "pps")}</dd>
        <dt>Stream</dt><dd>{edge.identity?.stream_key ?? "-"}</dd>
        <dt>Flow</dt><dd>{edge.identity?.flow_key ?? "-"}</dd>
