.topology-pane {
  gap: var(--space-2);
}

.topology-header {
  min-height: var(--pane-header-height);
  padding: 0 var(--space-2);
  border-radius: var(--radius-md);
  box-shadow: none;
}

.topology-header h2 {
  margin: 0;
  font-size: var(--font-size-sm);
}

.topology-header-main {
  flex: 1 1 auto;
  display: flex;
  align-items: center;
  min-width: 0;
  gap: var(--space-2);
}

.topology-header-meta {
  min-width: 0;
  overflow: hidden;
  color: var(--muted);
  font-size: var(--font-size-xs);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.topology-badges {
  gap: var(--space-1);
}

.topology-search {
  width: clamp(180px, 19vw, 270px);
}

.topology-badges button,
.topology-badges span,
.topology-layout-mode {
  min-height: 24px;
  padding: 0 7px;
  border-radius: var(--radius-sm);
  font-size: var(--font-size-xs);
}

.topology-layout-mode {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  color: var(--muted);
  background: var(--surface-muted);
}

.topology-layout-mode select {
  min-height: 22px;
  border: 0;
  padding: 0 2px;
  color: var(--text);
  background: transparent;
  font: inherit;
}

.topology-body {
  gap: var(--space-2);
}

.topology-refresh-notice {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-2);
  padding: var(--space-1) var(--space-2);
  border: 1px solid var(--warning);
  border-radius: var(--radius-sm);
  background: var(--warning-soft);
  color: var(--warning);
  font-size: var(--font-size-xs);
}

.topology-refresh-notice button,
.topology-empty button {
  min-height: 24px;
  padding: 0 var(--space-2);
  border: 1px solid currentColor;
  border-radius: var(--radius-sm);
  background: transparent;
  color: inherit;
  font: inherit;
  font-weight: 700;
  cursor: pointer;
}

.topology-map-card,
.topology-side-card {
  border-radius: var(--radius-md);
  box-shadow: none;
}

.topology-side-card {
  padding: var(--space-2);
}

.topology-flow,
.topology-flow .react-flow__background {
  background: var(--surface-muted);
}

.topology-flow .react-flow__minimap,
.topology-flow .react-flow__controls {
  border-radius: var(--radius-sm);
  box-shadow: none;
}

.topology-flow .react-flow__controls-button {
  width: 26px;
  height: 26px;
}

.topology-rf-node,
.topology-schema-node,
.topology-schema-header,
.topology-schema-body,
.topology-schema-row:last-child {
  border-radius: var(--radius-md);
}

.topology-schema-node {
  box-shadow: none;
}

.topology-schema-header {
  min-height: 30px;
  padding: 6px var(--space-2);
  background: color-mix(in srgb, var(--accent) 8%, var(--surface));
}

.topology-schema-header strong {
  font-size: var(--font-size-sm);
}

.topology-schema-body {
  border-radius: 0 0 var(--radius-md) var(--radius-md);
}

.topology-schema-row,
.topology-schema-handle {
  min-height: 26px;
  height: 26px;
}

.topology-schema-row {
  font-size: var(--font-size-xs);
}

.topology-schema-row.selected::before {
  width: 2px;
}

.topology-rf-handle {
  width: 8px;
  height: 8px;
  border-width: 1px;
}

.topology-edge-label {
  border-radius: var(--radius-sm);
  box-shadow: var(--shadow-sm);
  font-size: var(--font-size-xs);
  padding: 3px 5px;
}

.topology-flow .react-flow__edge.topology-rf-edge .react-flow__edge-path {
  stroke-opacity: .68;
  transition: stroke-width .18s ease, stroke-opacity .18s ease;
}

.topology-flow .react-flow__edge.topology-rf-edge.stale .react-flow__edge-path {
  stroke-dasharray: 6 5;
  stroke-opacity: .4;
}

.topology-rf-node-stale,
.topology-schema-node-stale {
  opacity: .52;
}

.topology-schema-node-stale {
  border-color: color-mix(in srgb, var(--muted) 65%, var(--line));
  filter: saturate(.32);
}

.topology-edge-label.stale {
  color: var(--muted);
  border-color: color-mix(in srgb, var(--muted) 55%, var(--line));
  background: color-mix(in srgb, var(--surface-muted) 86%, var(--muted));
  opacity: .76;
}

.topology-schema-row-more {
  justify-content: center;
  color: var(--muted);
}

.topology-edge-actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-1);
  margin-top: var(--space-2);
}

.topology-edge-actions button {
  min-height: 26px;
  font-size: var(--font-size-xs);
}

.topology-flow .react-flow__edge.topology-rf-edge.selected .react-flow__edge-path {
  stroke-opacity: 1;
}

/* Search leaves the full graph operable: matching paths gain emphasis while unrelated context recedes. */
.topology-rf-node-search-match:not(.topology-rf-node-selected) .topology-schema-node {
  border-color: color-mix(in srgb, var(--warning) 75%, var(--line));
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--warning) 22%, transparent), var(--shadow-sm);
}

.topology-rf-node-search-dim {
  opacity: .28;
  filter: saturate(.4);
}

.topology-flow .react-flow__edge.topology-rf-edge.search-match:not(.selected) .react-flow__edge-path {
  stroke-opacity: 1;
  filter: drop-shadow(0 0 4px color-mix(in srgb, var(--warning) 50%, transparent));
}

.topology-flow .react-flow__edge.topology-rf-edge.search-dim:not(.selected) .react-flow__edge-path {
  stroke-opacity: .16;
}

.topology-edge-label.search-match:not(.selected) {
  border-color: color-mix(in srgb, var(--warning) 55%, var(--line));
  background: color-mix(in srgb, var(--warning) 13%, var(--surface));
}

.topology-edge-label.search-dim:not(.selected) {
  opacity: .3;
}

/* Topology is a single flat pane rather than a detached toolbar and card. */
.main-tab-topology .topology-tab-view {
  min-height: 0;
  height: 100%;
  display: grid;
}

.main-tab-topology .topology-pane {
  min-height: 0;
  height: 100%;
  display: grid;
  grid-template-rows: var(--pane-header-height) minmax(0, 1fr);
  gap: 0;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  background: var(--surface);
}

.main-tab-topology .topology-header {
  min-height: var(--pane-header-height);
  margin: 0;
  padding: 0 var(--space-2);
  border: 0;
  border-bottom: 1px solid var(--line);
  border-radius: 0;
  background: var(--surface);
}

.main-tab-topology .topology-body {
  min-height: 0;
  padding: var(--space-2);
  gap: var(--space-2);
  background: var(--surface);
}

.dashboard-cell-body .topology-pane {
  grid-template-rows: minmax(0, 1fr);
}
