export type TopologyGraphNode = {
  id: string;
  label: string;
  type: "host" | "group";
  host: string;
  services: TopologyService[];
  alert?: boolean;
  state: "active" | "stale";
  x: number;
  y: number;
};

export type TopologyGraphEdge = TopologyEdge & {
  srcHostId: string;
  dstHostId: string;
  srcServiceKey?: string;
  dstServiceKey?: string;
  scopeKey: string;
  scopeLabel: string;
};

export type TopologyGraphScope = {
  key: string;
  label: string;
