.topology-header h2 {
  margin: 0;
  font-size: var(--font-size-sm);
}

.topology-header-main {
  flex: 1 1 auto;
  display: flex;
  align-items: center;
  min-width: 0;
  gap: var(--space-2);
}

.topology-header-meta {
  min-width: 0;
  overflow: hidden;
  color: var(--muted);
  font-size: var(--font-size-xs);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.topology-badges {
  gap: var(--space-1);
}

.topology-search {
  width: clamp(180px, 19vw, 270px);
}

.topology-badges button,
.topology-badges span,
.topology-layout-mode {
  min-height: 24px;
  padding: 0 7px;
  border-radius: var(--radius-sm);
  font-size: var(--font-size-xs);
}

.topology-badges .icon-only,
.topology-selection-controls .icon-only,
.topology-edge-actions .icon-only {
  width: 26px;
  min-width: 26px;
  height: 26px;
}

.topology-badges button.active,
.topology-selection-controls button.active {
  border-color: var(--accent-border);
  background: var(--accent-soft);
  color: var(--accent);
}

.topology-layout-mode {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  color: var(--muted);
  background: var(--surface-muted);
}

.topology-layout-mode select {
  min-height: 22px;
  border: 0;
  padding: 0 2px;
  color: var(--text);
  background: transparent;
  font: inherit;
}

.topology-body {
  gap: var(--space-2);
}

.topology-refresh-notice {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-2);
  padding: var(--space-1) var(--space-2);
  border: 1px solid var(--warning);
  border-radius: var(--radius-sm);
  background: var(--warning-soft);
  color: var(--warning);
  font-size: var(--font-size-xs);
}

.topology-refresh-notice button,
  display: grid;
}

.main-tab-topology .topology-pane {
  min-height: 0;
  height: 100%;
  display: grid;
  grid-template-rows: var(--pane-header-height) minmax(0, 1fr);
  gap: 0;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  background: var(--surface);
}

.main-tab-topology .topology-header {
  min-height: var(--pane-header-height);
  margin: 0;
  padding: 0 var(--space-2);
  border: 0;
  border-bottom: 1px solid var(--line);
  border-radius: 0;
  background: var(--surface);
}

.main-tab-topology .topology-body {
  min-height: 0;
  padding: var(--space-2);
  gap: var(--space-2);
  background: var(--surface);
}

.dashboard-cell-body .topology-pane {
  grid-template-rows: minmax(0, 1fr);
}

