          {mapMode === "service" && <button type="button" className={"icon-only " + (activeOnly ? "active" : "")} aria-pressed={activeOnly} onClick={() => setActiveOnly((value) => !value)} aria-label={activeOnly ? "Show stale relations" : "Show active relations only"} title={activeOnly ? "Show stale relations" : "Show active relations only"}><Icon name="filter" size={15} /></button>}
