              proOptions={{ hideAttribution: true }}
              onInit={() => {
                if (diagnostic) console.info("[STM_DIAG] topology client init", { width: mapCardRef.current?.clientWidth ?? 0, height: mapCardRef.current?.clientHeight ?? 0 });
              }}
              onEdgeClick={(_, edge) => { if (edge.data?.edge) handleEdgeSelect(edge.data.edge); }}
              onEdgeDoubleClick={(_, edge) => { if (edge.data?.edge) openInspectorForEdge(edge.data.edge); }}
              onPaneClick={clearEdgeSelection}
              onNodeClick={(_, node) => {
                clearEdgeSelection();
                setSelectedHostId(node.id);
              }}
              onNodeDragStop={(_, node) => {
                manualNodePositions.current.set(node.id, { x: node.position.x, y: node.position.y });
                setPositionVersion((value) => value + 1);
              }}
            >
              <TopologyRenderLifecycle
                nodeIds={flowNodeIds}
                renderKey={topologyRenderKey}
                fitRequest={fitRequest}
                mapCardRef={mapCardRef}
                diagnostic={diagnostic}
                onReady={handleTopologyReady}
              />
              <Background gap={28} size={1} />
              <MiniMap pannable zoomable nodeStrokeWidth={3} position={dashboard ? "top-right" : "bottom-right"} />
              <Controls showInteractive={false} />
            </ReactFlow>
          )}
          {!topologyReady && graph.nodes.length > 0 && <div className="dashboard-cell-loading-overlay" role="status" aria-live="polite"><div className="dashboard-cell-loading-dialog"><div className="timeline-loading-spinner" /><span>Preparing topology…</span></div></div>}
          {dashboard && focusedTargetMissing && <div className="dashboard-topology-focus-status" role="status">Focused target is not present at this time</div>}
          {dashboard && selectedEdge && <DashboardEdgeSelectionPanel edge={selectedEdge} onClear={clearEdgeSelection} onInspect={() => { handleEdgeNavigation(selectedEdge); clearEdgeSelection(); }} />}
        </div>
        <aside className="topology-side-card">
          <TopologyMapStatus snapshot={mapSnapshot} mapMode={effectiveMapMode} activeOnly={effectiveActiveOnly} frozen={Boolean(frozenSnapshot)} snapshotTimeIsGlobal={snapshotTimeIsGlobal} />
          <section className="topology-selection-section">
            <div className="topology-selection-heading">
      </div>
    </section>
  );
}

type TopologyRenderLifecycleProps = {
  nodeIds: string[];
  renderKey: string;
  fitRequest: number;
  mapCardRef: { current: HTMLDivElement | null };
  diagnostic: boolean;
  onReady: (renderKey: string) => void;
};

function TopologyRenderLifecycle({ nodeIds, renderKey, fitRequest, mapCardRef, diagnostic, onReady }: TopologyRenderLifecycleProps) {
  const reactFlow = useReactFlow<Node<TopologyNodeData>, TopologyFlowEdge>();
  const nodesInitialized = useNodesInitialized();
  const updateNodeInternals = useUpdateNodeInternals();
  const completedRequest = useRef<string | null>(null);

  useEffect(() => {
    if (nodeIds.length === 0) return;
    const mapCard = mapCardRef.current;
    if (!mapCard) return;
    const requestKey = `${renderKey}:${fitRequest}`;
    if (completedRequest.current === requestKey) {
      onReady(renderKey);
      return;
    }

    let cancelled = false;
    let firstFrame = 0;
    let secondFrame = 0;
    let retryTimer: number | undefined;
    let attempts = 0;

    const complete = (fitted: boolean) => {
      if (cancelled) return;
      completedRequest.current = requestKey;
      if (diagnostic) console.info("[STM_DIAG] topology client ready", {
        width: mapCard.clientWidth,
        height: mapCard.clientHeight,
        nodesInitialized,
        flowNodes: reactFlow.getNodes().length,
        flowEdges: reactFlow.getEdges().length,
        renderedEdges: mapCard.querySelectorAll(".react-flow__edge").length,
        fitted,
        viewport: reactFlow.getViewport()
      });
      onReady(renderKey);
    };

    const fit = async () => {
      if (cancelled) return;
      if (mapCard.clientWidth <= 0 || mapCard.clientHeight <= 0) return;
      const fitted = await reactFlow.fitView({ padding: 0.06, duration: 0, includeHiddenNodes: false });
      if (cancelled) return;
      if (!fitted && attempts < 2) {
        attempts += 1;
        retryTimer = window.setTimeout(scheduleFit, 0);
        return;
      }
      complete(fitted);
    };

    const scheduleFit = () => {
      if (cancelled || completedRequest.current === requestKey) return;
      window.cancelAnimationFrame(firstFrame);
      window.cancelAnimationFrame(secondFrame);
      if (retryTimer !== undefined) window.clearTimeout(retryTimer);
      /* Custom service rows own the handles, so force their bounds to be refreshed before fitting. */
      updateNodeInternals(nodeIds);
      firstFrame = window.requestAnimationFrame(() => {
        secondFrame = window.requestAnimationFrame(() => { void fit(); });
      });
    };

    const observer = new ResizeObserver(scheduleFit);
    observer.observe(mapCard);
    scheduleFit();
    return () => {
      cancelled = true;
      window.cancelAnimationFrame(firstFrame);
      window.cancelAnimationFrame(secondFrame);
      if (retryTimer !== undefined) window.clearTimeout(retryTimer);
      observer.disconnect();
    };
  }, [diagnostic, fitRequest, mapCardRef, nodeIds, nodesInitialized, onReady, reactFlow, renderKey, updateNodeInternals]);

  return null;
}

function TopologyMapStatus({ snapshot, mapMode, activeOnly, frozen, snapshotTimeIsGlobal }: { snapshot: TopologySnapshot | null; mapMode: TopologyMapMode; activeOnly: boolean; frozen: boolean; snapshotTimeIsGlobal: boolean }) {
  const unit = mapMode === "flow" ? "flows" : "relations";
  const staleCount = staleEdgeCount(snapshot);
  const alerts = alertCount(snapshot);
  return <section className="topology-map-status" aria-label="Topology map status">
    <h3>Map status</h3>
    {snapshot ? <>
      <dl>
        <dt>Active</dt><dd>{activeEdgeCount(snapshot)} {unit}</dd>

