export class MaintenanceSettings {
  private revision = 0;
  private values: RuntimeSettings;
  private writeQueue = Promise.resolve();

  private constructor(
    private readonly definition: SettingsDefinition,
    private readonly runtimeFile: string,
    defaults: RuntimeSettings
  ) {
    this.values = { ...defaults };
  }

  static async load(options: { definitionFile: string; runtimeFile: string; defaults: RuntimeSettings }) {
    const definition = parseDefinition(JSON.parse(await readFile(options.definitionFile, "utf8")));
    const settings = new MaintenanceSettings(definition, options.runtimeFile, options.defaults);
    if (!existsSync(options.runtimeFile)) return settings;

    try {
      const persisted = JSON.parse(await readFile(options.runtimeFile, "utf8")) as { revision?: unknown; values?: unknown };
      settings.values = settings.validateValues({ ...settings.values, ...migratePersistedValues(persisted.values) });
      settings.revision = Number.isInteger(persisted.revision) && Number(persisted.revision) >= 0 ? Number(persisted.revision) : 0;
    } catch (error) {
      console.warn(`maintenance settings: ignoring invalid runtime file ${options.runtimeFile}: ${String(error)}`);
    }
    return settings;
  }

  get(): MaintenanceSettingsResponse {
    return { revision: this.revision, sections: this.definition.sections, values: { ...this.values } };
  }

  update(revision: unknown, values: unknown) {
    const operation = this.writeQueue.then(async () => {
      if (!Number.isInteger(revision) || Number(revision) !== this.revision) {
        throw new SettingsConflictError("settings changed on the server; reload before saving");
      }
      const next = this.validateValues(values);
      const nextRevision = this.revision + 1;
      const temporary = path.join(path.dirname(this.runtimeFile), `.${path.basename(this.runtimeFile)}.${process.pid}.tmp`);
      await writeFile(temporary, `${JSON.stringify({ version: 1, revision: nextRevision, values: next }, null, 2)}\n`, "utf8");
      await rename(temporary, this.runtimeFile);
      this.values = next;
      this.revision = nextRevision;
      return this.get();
    });
