    return operation;
  }

  private validateValues(input: unknown): RuntimeSettings {
    if (!input || typeof input !== "object" || Array.isArray(input)) throw new SettingsValidationError("values must be an object");
    const source = input as Record<string, unknown>;
    const definitions = this.definition.sections.flatMap((section) => section.settings);
    const expected = new Set(definitions.map((setting) => setting.key));
    for (const key of Object.keys(source)) {
      if (!expected.has(key as keyof RuntimeSettings)) throw new SettingsValidationError(`unknown setting: ${key}`);
    }

    const result = {} as RuntimeSettings;
    for (const setting of definitions) {
      const value = source[setting.key];
      if (setting.type === "boolean") {
        if (typeof value !== "boolean") throw new SettingsValidationError(`${setting.key} must be boolean`);
        result[setting.key] = value as never;
        continue;
      }
      if (typeof value !== "number" || !Number.isInteger(value)) throw new SettingsValidationError(`${setting.key} must be an integer`);
      if (setting.min !== undefined && value < setting.min) throw new SettingsValidationError(`${setting.key} must be at least ${setting.min}`);
      if (setting.max !== undefined && value > setting.max) throw new SettingsValidationError(`${setting.key} must be at most ${setting.max}`);
      if (setting.options && !setting.options.some((option) => option.value === value)) throw new SettingsValidationError(`${setting.key} is not an allowed value`);
      result[setting.key] = value as never;
    }
