import { SocketServer } from "./ws/socketServer";
import { MaintenanceSettings } from "./maintenanceSettings";
import { AlertsSettings } from "./alertsSettings";
import { ProtocolMapSettings } from "./protocolMapSettings";

type RunningTail = { start(): void; stop(): void };

async function main() {
  ensureLogFilesExist();
  diagnostic(`startup source=projected cwd=${process.cwd()} root=${config.rootDir} logDir=${config.logDir} port=${config.port}`);
  diagnosticInputs();

  const app = fastify({ logger: config.httpAccessLog });
  const alertsSettings = config.stmConfigFile ? new AlertsSettings(config.stmConfigFile) : undefined;
  const protocolMapSettings = config.stmConfigFile ? new ProtocolMapSettings(config.stmConfigFile) : undefined;
  const maintenanceSettings = await MaintenanceSettings.load({
    definitionFile: config.maintenanceSettingsFile,
    runtimeFile: config.runtimeSettingsFile,
    defaults: { lostRetentionSec: config.lostRetentionSec, historyWindowSec: config.historyWindowSec, staleAfterSec: config.staleAfterSec, diagnosticLog: config.diagnosticLog, dashboardLayoutEditMode: config.dashboardLayoutEditMode, streamsErrorCountMode: config.streamsErrorCountMode, streamsRecentAlertRetentionMin: config.streamsRecentAlertRetentionMin, streamsAlertDisplay: config.streamsAlertDisplay, historicalSparklines: config.historicalSparklines, streamsSparklineSamples: config.streamsSparklineSamples }
  });
  Object.assign(config, maintenanceSettings.get().values);
  const store = new StreamStore(config.historyWindowSec, config.timelineWindowSec, config.lostRetentionSec, config.maxEvents, config.maxTimelineRows, config.topologyStaleRetentionSec, config.topologyMaxStaleEdges, config.topologyMaxDetailFlowsPerRelation, config.streamsErrorCountMode, config.streamsSparklineSamples);
  const now = Date.now() / 1000;
  const initialEvents = await queryEventsHistory({ from: now - 24 * 3600, to: now, limit: config.maxEvents });
  for (const event of initialEvents.reverse()) store.addEvent(event);

  const initialTopology = await queryProjectedTopologyAt({ checkpointDir: config.topologyCheckpointDir, updatesDir: config.topologyUpdatesDir, time: now });
  if (initialTopology) store.applyTopologySnapshot(initialTopology);
  diagnostic(`initial state events=${store.listEvents({ limit: config.maxEvents }).length} topology=${initialTopology ? "loaded" : "missing"}`);

  const sockets = new SocketServer(app.server, store, config.streamsPatchIntervalMs, config.wsMaxBufferedBytes);
  await registerRoutes(app, store, maintenanceSettings, alertsSettings, protocolMapSettings, (values) => {
    Object.assign(config, values);
    store.updateRuntimeConfig(values);
    sockets.broadcastConfig(values);
  });
  if (existsSync(config.externalPagesDir)) {
    await app.register(fastifyStatic, { root: config.externalPagesDir, prefix: "/external-pages/", decorateReply: false });
  }
  if (existsSync(config.localesDir)) {
    await app.register(fastifyStatic, { root: config.localesDir, prefix: "/locales/", decorateReply: false, setHeaders: (response) => response.setHeader("Cache-Control", "no-store") });
  }
  if (existsSync(config.clientDist)) {
    await app.register(fastifyStatic, { root: config.clientDist, prefix: "/" });
    app.setNotFoundHandler((request, reply) => {
      if (request.raw.url?.startsWith("/api") || request.raw.url === "/ws" || request.raw.url?.startsWith("/external-pages/") || request.raw.url?.startsWith("/locales/")) return reply.code(404).send({ error: "not found" });
      return reply.sendFile("index.html");
