                        <button type="button" className={"icon-only " + (!timelineFollowNow ? "active" : "")} onClick={() => { setTimelineFollowNow(false); setManualTimelineWindowEndSec(timelineWindow.to); }} aria-label="Browse timeline" title="Browse timeline"><Icon name="timeline" size={15} /></button>
                      </div>
                    </div>}
                  />}
                >
                  <div className="timeline-body pane-timeline-body">
                    <PaneLoadingOverlay state={timelineLoadState} label={t("common.loadingTimeline")} />
                    <TimelinePane
                      rows={filteredTimeline}
                      gaps={timelineGaps}
                      nowSec={tabContextTimeSec ?? summary.updatedAt ?? Date.now() / 1000}
                      fadeSec={appConfig.lostRetentionSec}
                      rangeStartSec={timelineWindow.from}
                      rangeEndSec={timelineWindow.to}
                      expandLevel={timelineExpandLevel}
                      selectedTimeSec={tabContextTimeSec}
                      onSelectTime={selectGlobalTime}
                      events={timelineEvents}
                      selectedEventId={selectedEvent?.id ?? null}
                      onSelectEvent={selectGlobalEvent}
                      onInspectTarget={(row) => {
                        if (row.rowType === "flow" && row.flowKey) selectInspectorFlow(row.streamKey, row.flowKey);
                        else selectInspectorStream(row.streamKey);
                        openInspectorContext();
                      }}
                      interfaceNames={timelineInterfaceNames}
                      onPanBySec={panTimelineBySec}
                      onZoom={zoomTimeline}
                    />
                  </div>
                </PaneFrame>
              )}
              {activeTab === "topology" && (
                <section className="standalone-view topology-tab-view">
                  <TopologyPane
                    streamDisplayNames={new Map(streams.flatMap((stream) => stream.displayName ? [[stream.streamKey, stream.displayName] as const] : []))}
                    selectedTimeSec={tabLocalTimeSec}
                    updatedAt={summary.updatedAt}
                    onSelectStream={(streamKey) => {
                      setSelectedInterfaceKey(null);
                      setSelectedStreamKey(streamKey);
                      setSelectedFlowKey(null);
                    }}
                    onSelectFlow={(streamKey, flowKey) => {
                      setSelectedInterfaceKey(null);
                      setSelectedStreamKey(streamKey);
                      setSelectedFlowKey(flowKey);
                    }}
                    onSelectTime={selectGlobalTime}
                    onOpenInspector={openInspectorContext}
                  />
                </section>
              )}
              {activeTab === "events" && (
                <section className="standalone-view standalone-events">
                  <EventLog
                    events={events}
                    eventsRange={eventsRange}
                    onChangeEventsRange={setEventsRange}
                    selectedStreamKey={selectedStreamKey}
                    selectedFlowKey={selectedFlowKey}
                    selectedInterfaceId={selectedInterface?.interfaceId ?? null}
                    selectedTimeSec={tabContextTimeSec}
                    onSelectTime={selectGlobalTime}
                    selectedEvent={selectedEvent}
                    onSelectEvent={setSelectedEvent}
                    onInspectTarget={(event) => {
                      if (event.streamKey) event.flowKey ? selectInspectorFlow(event.streamKey, event.flowKey) : selectInspectorStream(event.streamKey);
                      else if (event.interfaceId !== undefined) { const item = interfaces.find((candidate) => candidate.interfaceId === event.interfaceId); if (item) selectInspectorInterface(item.key); }
                      openInspectorContext();
                    }}
                  />
                </section>
              )}
              {activeTab === "preferences" && (
                <PaneFrame
                  className="placeholder-tab-frame"
                  header={<PaneHeader title={t("nav.preferences")} icon="preferences" meta={t("nav.preferencesHint")} />}
                >
                  <div className="placeholder-tab-content" />
                </PaneFrame>
              )}
              {activeTab === "maintenance" && (
                <MaintenancePane
                  refreshToken={maintenanceRefreshToken}
                  onApplied={(nextConfig) => setAppConfig(nextConfig)}
                />
              )}
              {activeTab === "alerts" && <AlertsPane onSaved={setAlertDocument} />}
              {activeTab === "protocol-map" && <ProtocolMapPane onAlertSaved={setAlertDocument} />}
              {activeTab === "help" && (
                <PaneFrame
                  className="external-page-tab-frame"
                  header={<PaneHeader title={t("nav.help")} icon="help" meta={t("nav.helpHint")} />}
                >
                  <iframe className="external-page-frame" title={t("nav.help")} src="/external-pages/help/" />
                </PaneFrame>
              )}
              {renderInspectorContext()}
              {activeTab === "information" && (
                <PaneFrame
                  className="external-page-tab-frame"
                  header={<PaneHeader title={t("nav.information")} icon="information" meta={t("nav.informationHint")} />}
                >
                  <iframe className="external-page-frame" title={t("nav.information")} src="/external-pages/information/" />
                </PaneFrame>
              )}
            </section>
          )}
        </div>
      </div>
      {/* Strong guard against browser history swipe gestures during splitter drags; remove if it interferes with normal dragging. */}
      {resizingPane && <div className={`resize-capture resize-capture-${resizingPane}`} aria-hidden="true" />}
      <InspectorTargetDrawer
        open={inspectorTargetPickerOwner !== null}
        modal={false}
        streams={streams}
        interfaces={interfaces}
        showAlerts={appConfig.streamsAlertDisplay}
        recentAlertRetentionMin={appConfig.streamsRecentAlertRetentionMin}
        selectedStreamKey={inspectorPickerTarget?.kind === "interface" ? null : inspectorPickerTarget?.streamKey ?? null}
        selectedFlowKey={inspectorPickerTarget?.kind === "flow" ? inspectorPickerTarget.flowKey : null}
        selectedInterfaceKey={inspectorPickerTarget?.kind === "interface" ? inspectorPickerTarget.interfaceKey : null}
        onClose={() => setInspectorTargetPickerOwner(null)}
