        onSelectStream={(streamKey) => selectInspectorTargetFromPicker({ kind: "stream", streamKey })}
        onSelectFlow={(streamKey, flowKey) => selectInspectorTargetFromPicker({ kind: "flow", streamKey, flowKey })}
      />
    </main>
