const fs = require('fs');
const path = require('path');
const ts = require('./fe/node_modules/typescript');
const root = 'fe/client/src';
const files = [];
(function walk(dir) { for (const entry of fs.readdirSync(dir, { withFileTypes: true })) { const file = path.join(dir, entry.name); if (entry.isDirectory()) walk(file); else if (/\.(tsx|ts|jsx|js)$/.test(file)) files.push(file); } })(root);
let changed = 0;
let attributes = 0;
for (const file of files) {
  const text = fs.readFileSync(file, 'utf8');
