    if ((ts.isJsxOpeningElement(node) || ts.isJsxSelfClosingElement(node)) && ts.isIdentifier(node.tagName) && /^[a-z]/.test(node.tagName.text) && node.tagName.text !== 'iframe') {
      for (const property of node.attributes.properties) {
        if (ts.isJsxAttribute(property) && property.name.text === 'title') {
          edits.push({ start: property.name.getStart(source), end: property.name.getEnd(), text: 'data-tooltip' });
        }
      }
    }
    ts.forEachChild(node, visit);
  }
  visit(source);
  if (!edits.length) continue;
  let next = text;
  for (const edit of edits.sort((a, b) => b.start - a.start)) next = next.slice(0, edit.start) + edit.text + next.slice(edit.end);
  fs.writeFileSync(file, next);
  changed += 1;
  attributes += edits.length;
  console.log(`${file}: ${edits.length}`);
}
console.log(`migrated ${attributes} DOM tooltip attributes in ${changed} files`);
