}

.stm-tooltip::after {
  content: "";
  position: absolute;
  left: calc(var(--stm-tooltip-arrow-x) - 6px);
  width: 0;
  height: 0;
  border-right: 6px solid transparent;
  border-left: 6px solid transparent;
}

.stm-tooltip[data-side="above"]::after {
