  useEffect(() => {
    if (!opened) return;
    const onPointerDown = (event: PointerEvent) => { if (!rootRef.current?.contains(event.target as Node)) setOpened(false); };
    const onKeyDown = (event: KeyboardEvent) => { if (event.key === "Escape") setOpened(false); };
