  return <section className="alerts-rules-table-section"><h4>{title}</h4><div className="maintenance-table-wrap"><table className="maintenance-table alerts-table"><thead><tr><th>Enabled</th><th>Condition ID</th><th>Target</th><th>Protocol</th><th>Roles</th><th>Indicator</th><th>Metric</th><th>Type</th><th>Trigger</th><th>Recovery</th><th>Timing</th><th>Severity</th><th /></tr></thead><tbody>{rules.map((rule, index) => <ConditionRow key={rule.id + ":" + index} rule={rule} metrics={metrics} protocols={protocols} flowRoles={flowRoles} busy={busy} lockedIdentity={lockedIdentity} onUpdate={(patch) => update(index, patch)} onRemove={() => remove(index)} />)}{rules.length === 0 && <tr><td colSpan={13} className="alerts-empty">No conditions.</td></tr>}</tbody></table></div>{!lockedIdentity && <div className="protocol-map-row-actions"><button type="button" className="maintenance-secondary-button button-with-icon" disabled={busy} onClick={add}><Icon name="add" size={16} />Add condition</button></div>}</section>;
}

