  const setType = (next: AlertRule["type"]) => {
    if (next === "availability") onUpdate({ type: next, operator: undefined, error_threshold: undefined, recover_threshold: undefined, delta_threshold: undefined, inactive_after_sec: rule.inactive_after_sec ?? 5 });
    else if (next === "counter_delta") onUpdate({ type: next, operator: rule.operator ?? ">", error_threshold: undefined, recover_threshold: undefined, delta_threshold: rule.delta_threshold ?? 0, recover_after_sec: rule.recover_after_sec ?? 3, inactive_after_sec: undefined });
    else onUpdate({ type: "threshold", operator: rule.operator ?? ">", error_threshold: rule.error_threshold ?? 0, recover_threshold: rule.recover_threshold ?? rule.error_threshold ?? 0, delta_threshold: undefined, inactive_after_sec: undefined });
  };
  return <tr><td><button type="button" role="switch" aria-checked={rule.enabled !== false} className={"maintenance-switch " + (rule.enabled !== false ? "is-on" : "is-off")} disabled={busy} onClick={() => onUpdate({ enabled: rule.enabled === false })}>{rule.enabled === false ? "Off" : "On"}</button></td><td><input className="alerts-id-input" value={rule.id} disabled={busy || lockedIdentity} onChange={(event) => onUpdate({ id: event.target.value })} /></td><td><select value={target} disabled={busy || lockedIdentity} onChange={(event) => onUpdate({ target: event.target.value as AlertRule["target"] })}><option value="flow">Flow</option><option value="stream">Stream</option><option value="interface">Interface</option><option value="any">Any</option></select></td><td><select value={rule.proto ?? ""} disabled={busy || lockedIdentity} onChange={(event) => onUpdate({ proto: event.target.value || undefined })}><option value="">Any</option>{protocols.map((proto) => <option key={proto} value={proto}>{proto}</option>)}</select></td><td><input value={roles} disabled={busy || lockedIdentity || target !== "flow"} placeholder="media, data" onChange={(event) => onUpdate({ flow_roles: event.target.value.split(",").map((value) => value.trim()).filter(Boolean) })} data-tooltip={rule.proto ? "Available: " + (flowRoles[rule.proto] ?? []).join(", ") : undefined} /></td><td><select value={rule.indicator_category ?? "other"} disabled={busy || lockedIdentity} onChange={(event) => onUpdate({ indicator_category: event.target.value as AlertRule["indicator_category"] })}><option value="other">Other</option><option value="quality">Quality</option></select></td><td><select value={rule.metric} disabled={busy || lockedIdentity} onChange={(event) => onUpdate({ metric: event.target.value })}>{!selectableMetrics.some((metric) => metric.key === rule.metric) && <option value={rule.metric}>Current: {rule.metric} (not available for this target)</option>}{selectableMetrics.map((metric) => <option key={metric.key} value={metric.key}>{metric.key}</option>)}</select></td><td><select value={type} disabled={busy || lockedIdentity} onChange={(event) => setType(event.target.value as AlertRule["type"])}><option value="threshold">Threshold</option><option value="counter_delta">Counter delta</option><option value="availability">Availability</option></select>{type !== "availability" && <select value={rule.operator ?? ">"} disabled={busy || lockedIdentity} onChange={(event) => onUpdate({ operator: event.target.value as AlertRule["operator"] })}>{operators.map((operator) => <option key={operator} value={operator}>{operator}</option>)}</select>}</td><td>{type === "availability" ? <NumberInput value={rule.inactive_after_sec} disabled={busy} onChange={(inactive_after_sec) => onUpdate({ inactive_after_sec })} /> : <NumberInput value={type === "counter_delta" ? rule.delta_threshold : rule.error_threshold} disabled={busy} onChange={(value) => onUpdate(type === "counter_delta" ? { delta_threshold: value } : { error_threshold: value })} />}</td><td>{type === "availability" ? "Packet received" : <NumberInput value={type === "counter_delta" ? rule.recover_after_sec : rule.recover_threshold} disabled={busy} onChange={(value) => onUpdate(type === "counter_delta" ? { recover_after_sec: value } : { recover_threshold: value })} />}</td><td><TimingFields rule={rule} disabled={busy || lockedIdentity} onUpdate={onUpdate} /></td><td><select value={rule.severity ?? "warning"} disabled={busy} onChange={(event) => onUpdate({ severity: event.target.value })}>{severities.map((severity) => <option key={severity} value={severity}>{severity}</option>)}</select></td><td>{!lockedIdentity && <button type="button" className="maintenance-secondary-button icon-only" disabled={busy} onClick={onRemove} aria-label="Delete condition" data-tooltip="Delete condition"><Icon name="delete" size={16} /></button>}</td></tr>;
