import { Icon } from "./Icon";
type SearchInputProps = {
  value: string;
  onChange: (value: string) => void;
  placeholder: string;
  label: string;
  className?: string;
};

export function SearchInput({ value, onChange, placeholder, label, className = "" }: SearchInputProps) {
  return (
    <label className={`search-input ${className}`.trim()}>
      <Icon name="search" size={16} />
      <input value={value} onChange={(event) => onChange(event.target.value)} placeholder={placeholder} aria-label={label} />
      {value && (
        <button type="button" className="search-clear" onClick={() => onChange("")} aria-label={`Clear ${label}`} data-tooltip={`Clear ${label}`}>
          <Icon name="close" size={14} />
        </button>
      )}
    </label>
  );
}
