const MAX_STREAM_ROWS_PER_GROUP = 200;
const MAX_FLOW_ROWS_PER_STREAM = 80;
const STREAM_TABLE_OVERSCAN_PX = 600;
const STREAM_TABLE_ROW_HEIGHT = { interface: 48, scope: 48, proto: 48, stream: 48, group: 48, flow: 48, truncated: 32 };

type InterfaceGroup = {
  key: string;
  name: string;
  interfaceItem?: InterfaceListItem;
  streams: StreamListItem[];
};

type ScopeGroup = { key: string; label: string; streams: StreamListItem[] };
type StreamDisplayGroup = { key: string; label: string; confidence?: "confirmed" | "heuristic"; streams: StreamListItem[]; grouped: boolean };

type FlatRow = { treeLevel?: number } & (
  | { key: string; type: "interface"; height: number; group: InterfaceGroup }
  | { key: string; type: "scope"; height: number; group: ScopeGroup }
  | { key: string; type: "proto"; height: number; group: { key: string; proto: string; streams: StreamListItem[] } }
  | { key: string; type: "group"; height: number; group: StreamDisplayGroup }
  | { key: string; type: "stream"; height: number; stream: StreamListItem }
  | { key: string; type: "flow"; height: number; stream: StreamListItem; flow: FlowListItem }
  | { key: string; type: "truncated"; height: number; label: string; depth: "stream" | "flow" }
);


type TreeGuideData = {
  depth: number;
  ancestorDepths: number[];
  hasPreviousSibling: boolean;
  hasNextSibling: boolean;
};

type StickyContextItem = {
  kind: "interface" | "scope" | "proto" | "group" | "stream";
  label: string;
  proto?: string;
  title?: string;
};

type GuidedFlatRow = FlatRow & { treeGuide: TreeGuideData };
  });
}

function TreeGuideLines({ guide }: { guide: TreeGuideData }) {
  const ownSegments = [
    guide.hasPreviousSibling ? "incoming" : "",
    guide.hasNextSibling ? "outgoing" : ""
  ].filter(Boolean);
  return <span className="tree-guide-layer" aria-hidden="true">
    {guide.ancestorDepths.map((depth) => <span key={`ancestor-${depth}`} className={`tree-guide-line tree-guide-depth-${depth}`} />)}
    {ownSegments.map((segment) => <span key={segment} className={`tree-guide-line tree-guide-depth-${guide.depth} tree-guide-${segment}`} />)}
  </span>;
}

function AlertCountBadge({ counts }: { counts: AlertCounts }) {
  if (counts.active === 0 && counts.recent === 0) return null;
  return <span className={`stream-alert-count stream-alert-${counts.severity ?? "warning"}`} data-tooltip={[counts.active ? `${counts.active} active alert target${counts.active === 1 ? "" : "s"}` : "", counts.recent ? `${counts.recent} recovered recently` : ""].filter(Boolean).join(" · ")}>{counts.active > 0 && <b>!{counts.active}</b>}{counts.recent > 0 && <small>{counts.recent}</small>}</span>;
}

function alertCauseTitle(summary: StreamAlertSummary | undefined, state: "Active" | "Recent") {
  if (!summary) return "";
  const details = (summary.causes ?? []).map((cause) => (cause.category === "quality" ? "Quality" : "Other") + ": " + (cause.metric ?? cause.alertId));
  return [state, ...details].filter(Boolean).join(" · ");
}

function FlowAlertBadge({ alert, recentAlert }: { alert?: StreamAlertSummary; recentAlert?: StreamAlertSummary }) {
  const summary = alert ?? recentAlert;
  if (!summary) return null;
  return <span className={"stream-alert-count stream-alert-" + summary.severity} data-tooltip={alertCauseTitle(summary, alert ? "Active" : "Recent")}><b>!</b></span>;
}

type OtherAlert = { severity: StreamAlertSummary["severity"]; causes: StreamAlertSummary["causes"] };
function severityRank(value: StreamAlertSummary["severity"] | undefined) { return value === "critical" ? 3 : value === "error" ? 2 : value === "warning" ? 1 : 0; }
function activeOtherAlert(summaries: Array<StreamAlertSummary | undefined>): OtherAlert | undefined {
  const causes = summaries.flatMap((summary) => (summary?.causes ?? []).filter((cause) => cause.category === "other"));
  if (causes.length === 0) return undefined;
        }, 140);
      }}
