      {viewMode === "ranked" ? <RankedList entries={rankedEntries} rankTarget={rankTarget} selectedStreamKey={selectedStreamKey} selectedFlowKey={selectedFlowKey} overviewMode={overviewMode} pickerMode={pickerMode} showAlerts={showAlerts} recentAlertRetentionMin={recentAlertRetentionMin} referenceTimeSec={alertReferenceTimeSec} onSelectStream={selectStream} onSelectFlow={selectFlow} onAddToDashboard={onAddToDashboard} onInspect={onInspect} onRevealInTree={onRevealInTree} /> : <>
