type AlertCenterProps = {
  targets: AlertTarget[];
  counts: AlertCounts;
  timeTravel: boolean;
  onClearRecent: () => void;
  onOpenStreams: (target: AlertTarget) => void;
  onOpenInspector: (target: AlertTarget) => void;
  onOpenEvents: (target: AlertTarget) => void;
};

type Filter = "all" | "active" | "recent";

export function AlertCenter({ targets, counts, timeTravel, onClearRecent, onOpenStreams, onOpenInspector, onOpenEvents }: AlertCenterProps) {
  const [opened, setOpened] = useState(false);
  const [filter, setFilter] = useState<Filter>("all");
  const rootRef = useRef<HTMLDivElement>(null);
  const severity = counts.severity ?? "none";
  const visible = targets.filter((target) => filter === "all" || filter === "active" ? target.active : target.recent);

  useEffect(() => {
    if (!opened) return;
    const onPointerDown = (event: PointerEvent) => { if (!rootRef.current?.contains(event.target as Node)) setOpened(false); };
    const onKeyDown = (event: KeyboardEvent) => { if (event.key === "Escape") setOpened(false); };
    document.addEventListener("pointerdown", onPointerDown);
    document.addEventListener("keydown", onKeyDown);
    return () => {
      document.removeEventListener("pointerdown", onPointerDown);
      document.removeEventListener("keydown", onKeyDown);
    };
  }, [opened]);

  const open = (callback: (target: AlertTarget) => void, target: AlertTarget) => {
    callback(target);
    setOpened(false);
  };

  return <div ref={rootRef} className="alert-center">
    <button type="button" className={`alert-center-trigger is-${severity}`} aria-expanded={opened} aria-haspopup="dialog" onClick={() => setOpened((current) => !current)}>
      <span className="alert-center-dot" aria-hidden="true" />
      <span>Alert</span>
