import { useEffect, useLayoutEffect, useRef, useState, type CSSProperties, type ReactNode } from "react";
import { createPortal } from "react-dom";
import { useI18n } from "../../i18n";

type TooltipSide = "above" | "below";
type TooltipState = {
  target: HTMLElement;
  text: string;
  side: TooltipSide;
  x: number;
  y: number;
  arrowX: number;
};

type TooltipProviderProps = {
  delayMs: number;
  children: ReactNode;
};

const TOOLTIP_ID = "stm-global-tooltip";
const VIEWPORT_MARGIN = 8;
const TOOLTIP_GAP = 10;

export function TooltipProvider({ delayMs, children }: TooltipProviderProps) {
  const { t } = useI18n();
  const [tooltip, setTooltip] = useState<TooltipState | null>(null);
  const tooltipRef = useRef<HTMLDivElement | null>(null);
  const timerRef = useRef<number | null>(null);
  const pendingTargetRef = useRef<HTMLElement | null>(null);
  const activeTargetRef = useRef<HTMLElement | null>(null);
  const previousDescriptionRef = useRef<{ target: HTMLElement; value: string | null } | null>(null);

  const updatePosition = () => {
    setTooltip((current) => {
      if (!current || !current.target.isConnected) return null;
      const popup = tooltipRef.current;
      if (!popup) return current;
      const targetRect = current.target.getBoundingClientRect();
      const popupRect = popup.getBoundingClientRect();
      if (targetRect.width <= 0 || targetRect.height <= 0 || popupRect.width <= 0 || popupRect.height <= 0) return current;
      const side: TooltipSide = targetRect.top >= popupRect.height + TOOLTIP_GAP + VIEWPORT_MARGIN ? "above" : "below";
      const y = side === "above" ? targetRect.top - popupRect.height - TOOLTIP_GAP : targetRect.bottom + TOOLTIP_GAP;
      const x = clamp(targetRect.left + targetRect.width / 2 - popupRect.width / 2, VIEWPORT_MARGIN, window.innerWidth - popupRect.width - VIEWPORT_MARGIN);
      const arrowX = clamp(targetRect.left + targetRect.width / 2 - x, 12, popupRect.width - 12);
      if (current.side === side && current.x === x && current.y === y && current.arrowX === arrowX) return current;
      return { ...current, side, x, y, arrowX };
    });
  };

  useLayoutEffect(() => {
    if (!tooltip) return;
    const frame = window.requestAnimationFrame(updatePosition);
    return () => window.cancelAnimationFrame(frame);
  }, [tooltip]);

  useEffect(() => {
    const findTarget = (value: EventTarget | null) => value instanceof Element ? value.closest<HTMLElement>("[data-tooltip], [data-tooltip-key]") : null;
    const clearTimer = () => {
      if (timerRef.current !== null) window.clearTimeout(timerRef.current);
      timerRef.current = null;
      pendingTargetRef.current = null;
    };
    const removeDescription = () => {
      const previous = previousDescriptionRef.current;
      if (!previous) return;
      if (previous.value === null) previous.target.removeAttribute("aria-describedby");
      else previous.target.setAttribute("aria-describedby", previous.value);
      previousDescriptionRef.current = null;
    };
    const hide = () => {
      clearTimer();
      activeTargetRef.current = null;
      removeDescription();
      setTooltip(null);
    };
    const show = (target: HTMLElement) => {
      clearTimer();
      const key = target.getAttribute("data-tooltip-key");
      const text = key ? t(key, tooltipValues(target)) : target.getAttribute("data-tooltip")?.trim();
      if (!text || !target.isConnected) return;
      if (activeTargetRef.current === target) return;
      removeDescription();
      const previousDescription = target.getAttribute("aria-describedby");
      previousDescriptionRef.current = { target, value: previousDescription };
      target.setAttribute("aria-describedby", [previousDescription, TOOLTIP_ID].filter(Boolean).join(" "));
      activeTargetRef.current = target;
      setTooltip({ target, text, side: "below", x: -10_000, y: -10_000, arrowX: 12 });
    };
    const schedule = (target: HTMLElement, immediate: boolean) => {
      if (activeTargetRef.current === target || pendingTargetRef.current === target) return;
      clearTimer();
      if (immediate || delayMs <= 0) {
        show(target);
        return;
      }
"}

