function treeDepth(row: FlatRow) {
  if (row.treeLevel !== undefined) return row.treeLevel;
  switch (row.type) {
    case "interface": return 0;
    case "scope": return 1;
    case "proto": return 2;
    case "group": return 3;
    case "stream": return 4;
    case "flow": return 5;
    case "truncated": return row.depth === "stream" ? 4 : 5;
  }
}

function withTreeGuides(rows: FlatRow[]): GuidedFlatRow[] {
  const depths = rows.map(treeDepth);
  const nextSibling = rows.map((_, index) => {
    const depth = depths[index];
    for (let next = index + 1; next < rows.length; next += 1) {
      if (depths[next] < depth) return false;
      if (depths[next] === depth) return true;
    }
    return false;
  });
  const ancestry: Array<{ key: string; depth: number; hasNextSibling: boolean } | undefined> = [];
  const seenSiblings = new Set<string>();

  return rows.map((row, index) => {
    const depth = depths[index];
    ancestry.length = depth;
    const parentKey = ancestry.slice(0, depth).filter(Boolean).map((item) => item!.key).join("/") || "root";
    const siblingKey = `${parentKey}:${depth}`;
    const hasPreviousSibling = seenSiblings.has(siblingKey);
    seenSiblings.add(siblingKey);
    const guide = {
      depth,
      ancestorDepths: ancestry.slice(0, depth)
        .filter((item) => item?.hasNextSibling)
        .map((item) => item!.depth),
      hasPreviousSibling,
      hasNextSibling: nextSibling[index]
    };
    ancestry[depth] = { key: row.key, depth, hasNextSibling: nextSibling[index] };
    return { ...row, treeGuide: guide };
  });
}

