type TreeGuideData = {
  depth: number;
  ancestorDepths: number[];
  hasPreviousSibling: boolean;
  hasNextSibling: boolean;
};

type StickyContextItem = {
  kind: "interface" | "scope" | "proto" | "group" | "stream";
  label: string;
  proto?: string;
  title?: string;
};

type GuidedFlatRow = FlatRow & { treeGuide: TreeGuideData };

function treeDepth(row: FlatRow) {
  if (row.treeLevel !== undefined) return row.treeLevel;
  switch (row.type) {
    case "interface": return 0;
    case "scope": return 1;
    case "proto": return 2;
    case "group": return 3;
    case "stream": return 4;
    case "flow": return 5;
    case "truncated": return row.depth === "stream" ? 4 : 5;
  }
}

function withTreeGuides(rows: FlatRow[]): GuidedFlatRow[] {
  const depths = rows.map(treeDepth);
  const nextSibling = rows.map((_, index) => {
    const depth = depths[index];
    for (let next = index + 1; next < rows.length; next += 1) {
      if (depths[next] < depth) return false;
      if (depths[next] === depth) return true;
    }
    return false;
  });
  const ancestry: Array<{ key: string; depth: number; hasNextSibling: boolean } | undefined> = [];
  const seenSiblings = new Set<string>();

  return rows.map((row, index) => {
    const depth = depths[index];
    ancestry.length = depth;
    const parentKey = ancestry.slice(0, depth).filter(Boolean).map((item) => item!.key).join("/") || "root";
    const siblingKey = `${parentKey}:${depth}`;
    const hasPreviousSibling = seenSiblings.has(siblingKey);
    seenSiblings.add(siblingKey);
    const guide = {
      depth,
      ancestorDepths: ancestry.slice(0, depth)
        .filter((item) => item?.hasNextSibling)
        .map((item) => item!.depth),
      hasPreviousSibling,
      hasNextSibling: nextSibling[index]
    };
    ancestry[depth] = { key: row.key, depth, hasNextSibling: nextSibling[index] };
    return { ...row, treeGuide: guide };
  });
}

function TreeGuideLines({ guide }: { guide: TreeGuideData }) {
  const ownSegments = [
    guide.hasPreviousSibling ? "incoming" : "",
    guide.hasNextSibling ? "outgoing" : ""
  ].filter(Boolean);
  return <span className="tree-guide-layer" aria-hidden="true">
    {guide.ancestorDepths.map((depth) => <span key={`ancestor-${depth}`} className={`tree-guide-line tree-guide-depth-${depth}`} />)}
    {ownSegments.map((segment) => <span key={segment} className={`tree-guide-line tree-guide-depth-${guide.depth} tree-guide-${segment}`} />)}
  </span>;
}

function AlertCountBadge({ counts }: { counts: AlertCounts }) {
  if (counts.active === 0 && counts.recent === 0) return null;
  return <span className={`stream-alert-count stream-alert-${counts.severity ?? "warning"}`} data-tooltip={[counts.active ? `${counts.active} active alert target${counts.active === 1 ? "" : "s"}` : "", counts.recent ? `${counts.recent} recovered recently` : ""].filter(Boolean).join(" · ")}>{counts.active > 0 && <b>!{counts.active}</b>}{counts.recent > 0 && <small>{counts.recent}</small>}</span>;
}

function alertCauseTitle(summary: StreamAlertSummary | undefined, state: "Active" | "Recent") {
  if (!summary) return "";
  const details = (summary.causes ?? []).map((cause) => (cause.category === "quality" ? "Quality" : "Other") + ": " + (cause.metric ?? cause.alertId));
  return [state, ...details].filter(Boolean).join(" · ");
}

function FlowAlertBadge({ alert, recentAlert }: { alert?: StreamAlertSummary; recentAlert?: StreamAlertSummary }) {
  const summary = alert ?? recentAlert;
  if (!summary) return null;
  return <span className={"stream-alert-count stream-alert-" + summary.severity} data-tooltip={alertCauseTitle(summary, alert ? "Active" : "Recent")}><b>!</b></span>;
}

