    <div
      ref={tooltipRef}
      id={TOOLTIP_ID}
      className="stm-tooltip"
      role="tooltip"
      data-side={tooltip.side}
      style={{ left: tooltip.x, top: tooltip.y, "--stm-tooltip-arrow-x": `${tooltip.arrowX}px` } as CSSProperties}
    >
      {tooltip.text}
    </div>,
    document.body
  )}</>;
}

function clamp(value: number, min: number, max: number) {
  if (max < min) return min;
  return Math.min(Math.max(value, min), max);
}

function tooltipValues(target: HTMLElement) {
  const values: Record<string, string> = {};
  for (const [name, value] of Object.entries(target.dataset)) {
    if (!name.startsWith("tooltip") || name === "tooltip" || name === "tooltipKey" || value === undefined) continue;
    values[name.slice("tooltip".length).replace(/^[A-Z]/, (letter) => letter.toLowerCase())] = value;
  }
  return values;
}

