    };
    const handlePointerOut = (event: PointerEvent) => {
      const target = findTarget(event.target);
      if (!target || target === findTarget(event.relatedTarget)) return;
      if (target === activeTargetRef.current || target === pendingTargetRef.current) hide();
    };
    const handleFocusIn = (event: FocusEvent) => {
      const target = findTarget(event.target);
      if (target) schedule(target, true);
    };
    const handleFocusOut = (event: FocusEvent) => {
      const target = findTarget(event.target);
      if (target && target !== findTarget(event.relatedTarget) && target === activeTargetRef.current) hide();
    };
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") hide();
    };

    document.addEventListener("pointerover", handlePointerOver, true);
    document.addEventListener("pointerout", handlePointerOut, true);
    document.addEventListener("pointerdown", hide, true);
    document.addEventListener("focusin", handleFocusIn, true);
    document.addEventListener("focusout", handleFocusOut, true);
    document.addEventListener("keydown", handleKeyDown, true);
    window.addEventListener("resize", updatePosition);
    window.addEventListener("scroll", updatePosition, true);
    return () => {
      document.removeEventListener("pointerover", handlePointerOver, true);
      document.removeEventListener("pointerout", handlePointerOut, true);
      document.removeEventListener("pointerdown", hide, true);
      document.removeEventListener("focusin", handleFocusIn, true);
      document.removeEventListener("focusout", handleFocusOut, true);
      document.removeEventListener("keydown", handleKeyDown, true);
      window.removeEventListener("resize", updatePosition);
      window.removeEventListener("scroll", updatePosition, true);
      hide();
    };
  }, [delayMs, t]);

  return <>{children}{tooltip && typeof document !== "undefined" && createPortal(
    <div
      ref={tooltipRef}
      id={TOOLTIP_ID}
      className="stm-tooltip"
      role="tooltip"
      data-side={tooltip.side}
      style={{ left: tooltip.x, top: tooltip.y, "--stm-tooltip-arrow-x": `${tooltip.arrowX}px` } as CSSProperties}
    >
      {tooltip.text}
    </div>,
    document.body
  )}</>;
}

function clamp(value: number, min: number, max: number) {
  if (max < min) return min;
  return Math.min(Math.max(value, min), max);
}

function tooltipValues(target: HTMLElement) {
  const values: Record<string, string> = {};
  for (const [name, value] of Object.entries(target.dataset)) {
    if (!name.startsWith("tooltip") || name === "tooltip" || name === "tooltipKey" || value === undefined) continue;
    values[name.slice("tooltip".length).replace(/^[A-Z]/, (letter) => letter.toLowerCase())] = value;
  }
  return values;
}

