const files = execFileSync('rg', ['-l', 'data-tooltip-key', 'fe/client/src'], { encoding: 'utf8' }).trim().split('\n').filter(Boolean);
const missing = [];
for (const file of files) {
  const source = fs.readFileSync(file, 'utf8');
  for (const match of source.matchAll(/data-tooltip-key\s*=\s*["']([^"']+)["']/g)) {
    if (!definition.messages[match[1]]) missing.push(`${file}: ${match[1]}`);
  }
}
if (missing.length) { console.error(missing.join('\n')); process.exit(1); }
console.log(`static tooltip keys verified across ${files.length} files`);
