function FlowAlertBadge({ alert, recentAlert }: { alert?: StreamAlertSummary; recentAlert?: StreamAlertSummary }) {
  const { t } = useI18n();
  const summary = alert ?? recentAlert;
  if (!summary) return null;
  const details = (summary.causes ?? []).map((cause) => `${t(cause.category === "quality" ? "tooltip.alertCauseQuality" : "tooltip.alertCauseOther")}: ${cause.metric ?? cause.alertId}`);
  const tooltip = [t(alert ? "tooltip.alertActive" : "tooltip.alertRecent"), ...details].join(" · ");
  return <span className={"stream-alert-count stream-alert-" + summary.severity} data-tooltip={tooltip}><b>!</b></span>;
}

type OtherAlert = { severity: StreamAlertSummary["severity"]; causes: StreamAlertSummary["causes"] };
function severityRank(value: StreamAlertSummary["severity"] | undefined) { return value === "critical" ? 3 : value === "error" ? 2 : value === "warning" ? 1 : 0; }
function activeOtherAlert(summaries: Array<StreamAlertSummary | undefined>): OtherAlert | undefined {
  const causes = summaries.flatMap((summary) => (summary?.causes ?? []).filter((cause) => cause.category === "other"));
  if (causes.length === 0) return undefined;
  const severity = causes.reduce<StreamAlertSummary["severity"]>((highest, cause) => severityRank(cause.severity) > severityRank(highest) ? cause.severity : highest, "warning");
  return { severity, causes };
}
function otherAlertTitle(alert: OtherAlert | undefined) {
  if (!alert) return "No active non-quality alert";
  return alert.causes.map((cause) => (cause.metric ?? cause.alertId) + (cause.value !== undefined && cause.threshold !== undefined ? ": " + cause.value + " / " + cause.threshold : "")).join(" · ");
}

export function StreamTable({ streams, interfaces, selectedStreamKey, selectedFlowKey, selectedInterfaceKey, overviewMode = false, expandLevel = "flow", onSelectInterface, onSelectStream, onSelectFlow, onAddToDashboard, onInspect, pickerMode = false, timeTravel = false, showAlerts = true, recentAlertRetentionMin = 30, referenceTimeSec, dismissedRecent: dismissedRecentProp, onClearRecent, viewMode = "tree", rankTarget = "flows", sortOrder = "tree", onRevealInTree }: StreamTableProps) {
  const tableRef = useRef<HTMLDivElement>(null);
  const scrollingRef = useRef(false);
  const scrollIdleTimerRef = useRef<number | null>(null);
  const keyLabel = flowKey ? "Copy flow key" : "Copy stream key";
  const keyValue = flowKey ?? streamKey;

  useEffect(() => {
    const closeOtherMenu = (event: Event) => {
      if ((event as CustomEvent<string>).detail !== menuKey) setOpened(false);
    };
    document.addEventListener(ROW_ACTION_OPEN_EVENT, closeOtherMenu);
    return () => document.removeEventListener(ROW_ACTION_OPEN_EVENT, closeOtherMenu);
  }, [menuKey]);

  useEffect(() => {
    if (!opened) return;
    const onPointerDown = (event: PointerEvent) => {
      if (!menuRef.current?.contains(event.target as Node)) setOpened(false);
    };
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") setOpened(false);
    };
    document.addEventListener("pointerdown", onPointerDown);
    document.addEventListener("keydown", onKeyDown);
    return () => {
      document.removeEventListener("pointerdown", onPointerDown);
      document.removeEventListener("keydown", onKeyDown);
    };
  }, [opened]);

  const toggleMenu = () => {
    if (!opened) document.dispatchEvent(new CustomEvent(ROW_ACTION_OPEN_EVENT, { detail: menuKey }));
    setOpened((current) => !current);
  };
  const closeMenu = () => setOpened(false);

  return <span ref={menuRef} className="row-action-menu" onPointerDown={(event) => event.stopPropagation()} onClick={(event) => event.stopPropagation()}>
    <button type="button" className="row-action-trigger" aria-label="Open row actions" aria-expanded={opened} onClick={toggleMenu}><Icon name="more" size={17} /></button>
    {opened && <span className="row-action-popup" role="menu" aria-label="Row actions">
      {onInspect && <button type="button" role="menuitem" onClick={() => { closeMenu(); onInspect(streamKey, flowKey); }}><Icon name="detail" size={15} /><span>Inspect</span></button>}
      {onAddToDashboard && <button type="button" role="menuitem" onClick={() => { closeMenu(); onAddToDashboard(streamKey, flowKey); }}><Icon name="add" size={15} /><span>Add Inspector to Dashboard</span></button>}
      <button type="button" role="menuitem" onClick={() => { closeMenu(); void copyText(detailUrl); }}><Icon name="copy" size={15} /><span>Copy Inspector URL</span></button>
      <button type="button" role="menuitem" onClick={() => { closeMenu(); void copyText(keyValue); }}><Icon name="copy" size={15} /><span>{keyLabel}</span></button>
      {onRevealInTree && <button type="button" role="menuitem" onClick={() => { closeMenu(); onRevealInTree(streamKey, flowKey); }}><Icon name="streams" size={15} /><span>Reveal in Tree</span></button>}

