function FlowAlertBadge({ alert, recentAlert }: { alert?: StreamAlertSummary; recentAlert?: StreamAlertSummary }) {
  const { t } = useI18n();
  const summary = alert ?? recentAlert;
  if (!summary) return null;
  const details = (summary.causes ?? []).map((cause) => `${t(cause.category === "quality" ? "tooltip.alertCauseQuality" : "tooltip.alertCauseOther")}: ${cause.metric ?? cause.alertId}`);
  const tooltip = [t(alert ? "tooltip.alertActive" : "tooltip.alertRecent"), ...details].join(" · ");
  return <span className={"stream-alert-count stream-alert-" + summary.severity} data-tooltip={tooltip}><b>!</b></span>;
}

type OtherAlert = { severity: StreamAlertSummary["severity"]; causes: StreamAlertSummary["causes"] };
function severityRank(value: StreamAlertSummary["severity"] | undefined) { return value === "critical" ? 3 : value === "error" ? 2 : value === "warning" ? 1 : 0; }
function activeOtherAlert(summaries: Array<StreamAlertSummary | undefined>): OtherAlert | undefined {
  const causes = summaries.flatMap((summary) => (summary?.causes ?? []).filter((cause) => cause.category === "other"));
  if (causes.length === 0) return undefined;
  const severity = causes.reduce<StreamAlertSummary["severity"]>((highest, cause) => severityRank(cause.severity) > severityRank(highest) ? cause.severity : highest, "warning");
  return { severity, causes };
}
function otherAlertTitle(alert: OtherAlert | undefined) {
  if (!alert) return "No active non-quality alert";
  return alert.causes.map((cause) => (cause.metric ?? cause.alertId) + (cause.value !== undefined && cause.threshold !== undefined ? ": " + cause.value + " / " + cause.threshold : "")).join(" · ");
}

