type TopologyRenderLifecycleProps = {
  nodeIds: string[];
  edgeCount: number;
  handleGeometry: TopologyHandleGeometry[];
  handleGeometryKey: string;
  nodeSetKey: string;
  renderKey: string;
  fitRequest: number;
  mapCardRef: { current: HTMLDivElement | null };
  diagnostic: boolean;
  needsInitialPreparation: boolean;
  viewportUserAdjustedRef: { current: boolean };
  onReady: (renderKey: string) => void;
};

type TopologyRecoveryReason = "initial" | "manual" | "structure" | "resize" | "visibility";
type TopologyRecoveryScheduler = (reason: TopologyRecoveryReason, forceFit: boolean, nodesToMeasure?: string[], requireMissing?: boolean) => void;

function TopologyRenderLifecycle({ nodeIds, edgeCount, handleGeometry, handleGeometryKey, nodeSetKey, renderKey, fitRequest, mapCardRef, diagnostic, needsInitialPreparation, viewportUserAdjustedRef, onReady }: TopologyRenderLifecycleProps) {
  const reactFlow = useReactFlow<Node<TopologyNodeData>, TopologyFlowEdge>();
  const nodesInitialized = useNodesInitialized();
  const updateNodeInternals = useUpdateNodeInternals();
  const lastHandleGeometry = useRef<ReadonlyMap<string, string> | null>(null);
  const lastFitRequest = useRef<number | null>(null);
  const lastObservedSize = useRef<{ width: number; height: number } | null>(null);
  const lastRecoveryFitAt = useRef(0);
  const lastNodeSetKey = useRef<string | null>(null);
  const lifecycleRun = useRef(0);
  const latestTopologyState = useRef({ nodeIds, edgeCount, handleGeometry, renderKey, nodesInitialized, onReady });
  const recoverySchedulerRef = useRef<TopologyRecoveryScheduler | null>(null);
  latestTopologyState.current = { nodeIds, edgeCount, handleGeometry, renderKey, nodesInitialized, onReady };

  useEffect(() => {
    if (needsInitialPreparation) {
      lastNodeSetKey.current = nodeSetKey;
      return;
    }
    const previousNodeSetKey = lastNodeSetKey.current;
    lastNodeSetKey.current = nodeSetKey;
    const nodeSetChanged = previousNodeSetKey !== null && previousNodeSetKey !== nodeSetKey;
    if (!nodeSetChanged || viewportUserAdjustedRef.current) return;
    const mapCard = mapCardRef.current;
    if (!mapCard) return;
    const timer = window.setTimeout(() => {
      if (viewportUserAdjustedRef.current || mapCard.clientWidth <= 0 || mapCard.clientHeight <= 0) return;
      void reactFlow.fitView({ padding: 0.06, duration: 0, includeHiddenNodes: false }).then((fitted) => {
        if (diagnostic) console.info("[STM_DIAG] topology client settled fit", {
          delayMs: TOPOLOGY_SETTLED_FIT_DELAY_MS,
          flowNodes: reactFlow.getNodes().length,
          flowEdges: reactFlow.getEdges().length,
          fitted,
          viewport: reactFlow.getViewport()
        });
      });
    }, TOPOLOGY_SETTLED_FIT_DELAY_MS);
    return () => window.clearTimeout(timer);
  }, [diagnostic, mapCardRef, needsInitialPreparation, nodeSetKey, reactFlow, viewportUserAdjustedRef]);

  useEffect(() => {
    const initialTopologyState = latestTopologyState.current;
    if (initialTopologyState.nodeIds.length === 0) return;
    const mapCard = mapCardRef.current;
    if (!mapCard) return;
    lifecycleRun.current += 1;
    const firstLifecycleRender = lastHandleGeometry.current === null;
    const changedHandleNodeIds = firstLifecycleRender
      ? initialTopologyState.nodeIds
      : initialTopologyState.handleGeometry
        .filter(({ id, key }) => lastHandleGeometry.current?.get(id) !== key)
        .map(({ id }) => id);
    const handlesChanged = !firstLifecycleRender && changedHandleNodeIds.length > 0;
    const manualFitRequested = !needsInitialPreparation && lastFitRequest.current !== null && lastFitRequest.current !== fitRequest;
    lastHandleGeometry.current = new Map(initialTopologyState.handleGeometry.map(({ id, key }) => [id, key]));
    lastFitRequest.current = fitRequest;

    let cancelled = false;
    let firstFrame = 0;
    let secondFrame = 0;
    let retryTimer: number | undefined;
    let validationTimer: number | undefined;
    let attempts = 0;
    let recoveryGeneration = 0;

    const completeInitialPreparation = (fitted: boolean, reason: TopologyRecoveryReason) => {
      if (cancelled) return;
      if (diagnostic) console.info("[STM_DIAG] topology client ready", {
        reason,
        width: mapCard.clientWidth,
        height: mapCard.clientHeight,
        nodesInitialized: latestTopologyState.current.nodesInitialized,
        flowNodes: reactFlow.getNodes().length,
        flowEdges: reactFlow.getEdges().length,
        renderedEdges: mapCard.querySelectorAll(".react-flow__edge").length,
        fitted,
        viewport: reactFlow.getViewport()
      });
      latestTopologyState.current.onReady(latestTopologyState.current.renderKey);
    };

    const inspectRenderedTopology = () => {
      const topologyState = latestTopologyState.current;
      const renderedNodes = [...mapCard.querySelectorAll<HTMLElement>(".react-flow__node")];
      const renderedEdges = mapCard.querySelectorAll(".react-flow__edge").length;
      const cardRect = mapCard.getBoundingClientRect();
      const visibleNodeCount = cardRect.width <= 0 || cardRect.height <= 0 ? 0 : renderedNodes.filter((node) => {
        const rect = node.getBoundingClientRect();
        return rect.right > cardRect.left && rect.left < cardRect.right && rect.bottom > cardRect.top && rect.top < cardRect.bottom;
      }).length;
      const reason = renderedNodes.length < topologyState.nodeIds.length
        ? "missing-node-dom"
        : topologyState.edgeCount > 0 && renderedEdges < topologyState.edgeCount
          ? "missing-edge-dom"
          : cardRect.width > 0 && cardRect.height > 0 && visibleNodeCount === 0
            ? "no-visible-node"
            : "ready";
      return {
        reason,
        requiresRecovery: reason !== "ready",
        expectedNodes: topologyState.nodeIds.length,
        renderedNodes: renderedNodes.length,
        visibleNodes: visibleNodeCount,
        expectedEdges: topologyState.edgeCount,
        renderedEdges,
        cardWidth: Math.round(cardRect.width),
        cardHeight: Math.round(cardRect.height),
        flowNodes: reactFlow.getNodes().length,
        flowEdges: reactFlow.getEdges().length,
        viewport: reactFlow.getViewport(),
        viewportUserAdjusted: viewportUserAdjustedRef.current
      };
    };

    const needsRecoveryFit = () => inspectRenderedTopology().requiresRecovery;

    const runRecovery = async (reason: TopologyRecoveryReason, forceFit: boolean, generation: number) => {
      if (cancelled || generation !== recoveryGeneration) return;
      if (mapCard.clientWidth <= 0 || mapCard.clientHeight <= 0) return;
      const inspection = inspectRenderedTopology();
      const shouldFit = forceFit || inspection.requiresRecovery;
      if (!shouldFit) {
        if (diagnostic) console.info("[STM_DIAG] topology client geometry refreshed", {
          reason,
          width: mapCard.clientWidth,
          height: mapCard.clientHeight,
          flowNodes: reactFlow.getNodes().length,
          flowEdges: reactFlow.getEdges().length,
          renderedEdges: mapCard.querySelectorAll(".react-flow__edge").length,
          viewport: reactFlow.getViewport(),
          inspection
        });
        return;
      }
      if (!forceFit && Date.now() - lastRecoveryFitAt.current < TOPOLOGY_RECOVERY_FIT_COOLDOWN_MS) {
        if (diagnostic) console.info("[STM_DIAG] topology client recovery skipped", { reason, cooldownMs: TOPOLOGY_RECOVERY_FIT_COOLDOWN_MS, inspection });
        return;
      }
      if (diagnostic) console.info("[STM_DIAG] topology client recovery start", { reason, forceFit, inspection });
      if (!forceFit) lastRecoveryFitAt.current = Date.now();
      const fitted = await reactFlow.fitView({ padding: 0.06, duration: 0, includeHiddenNodes: false });
      if (cancelled || generation !== recoveryGeneration) return;
      if (forceFit && !fitted && attempts < 2) {
        attempts += 1;
        retryTimer = window.setTimeout(() => scheduleRecovery(reason, true), 0);
        return;
      }
      if (needsInitialPreparation) {
        completeInitialPreparation(fitted, reason);
      } else if (diagnostic) {
        console.info("[STM_DIAG] topology client recovery", {
          reason,
          width: mapCard.clientWidth,
          height: mapCard.clientHeight,
          flowNodes: reactFlow.getNodes().length,
          flowEdges: reactFlow.getEdges().length,
          renderedEdges: mapCard.querySelectorAll(".react-flow__edge").length,
          fitted,
          viewport: reactFlow.getViewport(),
          before: inspection,
          after: inspectRenderedTopology()
        });
      }
    };

    const scheduleRecovery: TopologyRecoveryScheduler = (reason, forceFit, nodesToMeasure, requireMissing = false) => {
      if (cancelled) return;
      if (requireMissing) {
        const inspection = inspectRenderedTopology();
        if (!inspection.requiresRecovery) {
          if (diagnostic) console.info("[STM_DIAG] topology client geometry refreshed", {
            reason,
            width: mapCard.clientWidth,
            height: mapCard.clientHeight,
            flowNodes: reactFlow.getNodes().length,
            flowEdges: reactFlow.getEdges().length,
            renderedEdges: mapCard.querySelectorAll(".react-flow__edge").length,
            viewport: reactFlow.getViewport(),
            inspection
          });
          return;
        }
      }
      recoveryGeneration += 1;
      const generation = recoveryGeneration;
      window.cancelAnimationFrame(firstFrame);
      window.cancelAnimationFrame(secondFrame);
      if (retryTimer !== undefined) window.clearTimeout(retryTimer);
      if (validationTimer !== undefined) window.clearTimeout(validationTimer);
      /* Custom service rows own the handles, so refresh only rows whose geometry can have changed. */
      const nodes = nodesToMeasure ?? latestTopologyState.current.nodeIds;
      if (nodes.length > 0) updateNodeInternals(nodes);
      firstFrame = window.requestAnimationFrame(() => {
        secondFrame = window.requestAnimationFrame(() => {
          if (forceFit) {
            void runRecovery(reason, true, generation);
            return;
          }
          /* Give React Flow one quiet paint before treating a transient edge update as a rendering failure. */
          validationTimer = window.setTimeout(() => { void runRecovery(reason, false, generation); }, 100);
        });
      });
    };

    const observeSize = () => {
      const next = { width: mapCard.clientWidth, height: mapCard.clientHeight };
      const previous = lastObservedSize.current;
      lastObservedSize.current = next;
      if (!previous || (previous.width === next.width && previous.height === next.height)) return;
      /* Resizing normally preserves the viewport; recover it only when the rendered map has actually disappeared. */
      scheduleRecovery(needsInitialPreparation ? "initial" : "resize", needsInitialPreparation);
    };

    const observer = new ResizeObserver(observeSize);
    observer.observe(mapCard);
    observeSize();
    recoverySchedulerRef.current = scheduleRecovery;
    if (needsInitialPreparation) scheduleRecovery("initial", true);
    else if (manualFitRequested) scheduleRecovery("manual", true);
    else if (firstLifecycleRender || handlesChanged) scheduleRecovery("structure", false, changedHandleNodeIds);
    return () => {
      cancelled = true;
      window.cancelAnimationFrame(firstFrame);
      window.cancelAnimationFrame(secondFrame);
      if (retryTimer !== undefined) window.clearTimeout(retryTimer);
      if (validationTimer !== undefined) window.clearTimeout(validationTimer);
      if (recoverySchedulerRef.current === scheduleRecovery) recoverySchedulerRef.current = null;
      observer.disconnect();
    };
  }, [diagnostic, fitRequest, handleGeometryKey, mapCardRef, needsInitialPreparation, nodeSetKey, reactFlow, updateNodeInternals]);

  useEffect(() => {
    if (needsInitialPreparation || viewportUserAdjustedRef.current) return;
    const lifecycleId = lifecycleRun.current;
    const topologyState = latestTopologyState.current;
    if (diagnostic) console.info("[STM_DIAG] topology client viewport check scheduled", {
      lifecycleId,
      delayMs: TOPOLOGY_VIEWPORT_VALIDATION_DELAY_MS,
      expectedNodes: topologyState.nodeIds.length,
      expectedEdges: topologyState.edgeCount,
      nodeSetKeyLength: nodeSetKey.length
    });
    const timer = window.setTimeout(() => {
      if (viewportUserAdjustedRef.current) return;
      if (diagnostic) console.info("[STM_DIAG] topology client viewport check", { lifecycleId });
      recoverySchedulerRef.current?.("visibility", false, undefined, true);
    }, TOPOLOGY_VIEWPORT_VALIDATION_DELAY_MS);
    return () => {
      window.clearTimeout(timer);
      if (diagnostic) console.info("[STM_DIAG] topology client viewport check cancelled", { lifecycleId });
    };
  }, [diagnostic, edgeCount, needsInitialPreparation, nodeSetKey, renderKey, viewportUserAdjustedRef]);

  return null;
}

function TopologyMapStatus({ snapshot, mapMode, activeOnly, frozen, snapshotTimeIsGlobal }: { snapshot: TopologySnapshot | null; mapMode: TopologyMapMode; activeOnly: boolean; frozen: boolean; snapshotTimeIsGlobal: boolean }) {
  const unit = mapMode === "flow" ? "flows" : "relations";
  const staleCount = staleEdgeCount(snapshot);
  const alerts = alertCount(snapshot);
