test('Streams toggles retain state, focus and geometry in all header layouts', { timeout: 60000 }, async t => {
  if (!fs.existsSync(chromePath)) return t.skip('Set CHROME_PATH to a Chromium executable');
  const fixture = `
    import React, {useState} from 'react';
    import {createRoot} from 'react-dom/client';
    import {StreamsViewControls} from './client/src/components/StreamsViewControls';
    import {I18nProvider, useI18n} from './client/src/i18n';
    import {TooltipProvider} from './client/src/components/ui/TooltipProvider';
    const orders=['tree','bitrate-desc','bitrate-asc','alerts-desc','last-seen-desc'];
    window.states={}; window.setups={};
    function Header({id}){
      const [state,setState]=useState({mode:'tree',target:'flows',order:'tree'});
      const {setLocale}=useI18n(); window.changeLocale=setLocale;
      window.states[id]=state; window.setups[id]=patch=>setState(s=>({...s,...patch}));
      return <section className='fixture' id={id}><div className={'pane-header'+(id==='standalone'?' standalone-toolbar':id==='dashboard'?' dashboard-cell-header':'')}>
        <div className='pane-header-copy'><span className='pane-header-title'>Streams</span></div>
        <div className={id==='dashboard'?'pane-header-actions dashboard-cell-actions':'pane-header-actions'}>
          <StreamsViewControls viewMode={state.mode} rankTarget={state.target} sortOrder={state.order}
            onChangeView={(mode,order)=>setState(s=>({...s,mode,order}))}
            onChangeRankTarget={target=>setState(s=>({...s,target}))}>
            {id==='dashboard'?<select aria-label='Streams sort order' value={state.order} onChange={e=>setState(s=>({...s,order:e.target.value}))}>
              {orders.map(order=><option key={order} value={order}>{order}</option>)}
            </select>:<button type='button' className='icon-only sort-control' aria-label='Sort' onClick={()=>setState(s=>({...s,order:orders[(orders.indexOf(s.order)+1)%orders.length]}))}>↓</button>}
          </StreamsViewControls>
        </div>
      </div></section>;
    }
    createRoot(document.getElementById('root')).render(<I18nProvider><TooltipProvider delayMs={0}>
      {['tab','standalone','dashboard'].map(id=><Header key={id} id={id}/>)}
    </TooltipProvider></I18nProvider>);
  `;
  const bundle = await esbuild.build({ stdin: { contents: fixture, resolveDir: path.join(repo, 'fe'), loader: 'tsx' }, bundle: true, write: false, platform: 'browser', jsx: 'automatic' });
  const css = ['styles.css', 'styles/tokens.css', 'styles/base.css', 'styles/panes.css', 'styles/dashboard.css', 'styles/header-controls.css', 'styles/tooltip.css']
    .filter(file => fs.existsSync(path.join(repo, 'fe/client/src', file)))
    .map(file => fs.readFileSync(path.join(repo, 'fe/client/src', file), 'utf8')).join('\n');
  const strings = fs.readFileSync(path.join(repo, 'fe/locales/strings.json'), 'utf8');
  const server = http.createServer((req, res) => {
    if (req.url === '/fixture.js') { res.setHeader('Content-Type', 'application/javascript'); res.end(bundle.outputFiles[0].text); return; }
    if (req.url === '/locales/strings.json') { res.setHeader('Content-Type', 'application/json'); res.end(strings); return; }
    res.setHeader('Content-Type', 'text/html');
    res.end(`<html><head><style>${css}\n.fixture{container-type:inline-size;margin-bottom:12px;width:100%}body{margin:0}.pane-header-title{white-space:nowrap}.list-toolbar-header{display:flex;justify-content:space-between}</style></head><body><div id='root'></div><script src='/fixture.js'></script></body></html>`);
  });
  await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
  const chrome = spawn(chromePath, ['--headless', '--no-sandbox', '--disable-dev-shm-usage', '--remote-debugging-port=0', 'about:blank'], { stdio: ['ignore', 'ignore', 'pipe'] });
  let log = ''; chrome.stderr.on('data', buffer => log += buffer);
  let socket;
  try {
    for (let i = 0; i < 100 && !log.includes('DevTools listening'); i++) await sleep(50);
    const port = log.match(/DevTools listening on ws:\/\/127\.0\.0\.1:(\d+)/)?.[1]; assert.ok(port, 'Chromium must start');
    const tab = await (await fetch(`http://127.0.0.1:${port}/json/new?http://127.0.0.1:${server.address().port}`, { method: 'PUT' })).json();
    socket = new WebSocket(tab.webSocketDebuggerUrl); await once(socket, 'open');
    let seq = 0; const pending = new Map(); const errors = [];
    socket.on('message', buffer => {
      const message = JSON.parse(buffer);
      if (message.id) { const p = pending.get(message.id); pending.delete(message.id); message.error ? p.reject(message.error) : p.resolve(message.result); }
      if (message.method === 'Runtime.exceptionThrown') errors.push(message.params);
    });
    const call = (method, params = {}) => new Promise((resolve, reject) => { const id = ++seq; pending.set(id, { resolve, reject }); socket.send(JSON.stringify({ id, method, params })); });
    const evaluate = async expression => { const result = await call('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true }); assert.ok(!result.exceptionDetails, JSON.stringify(result.exceptionDetails)); return result.result.value; };
    const wait = async expression => { for (let i = 0; i < 100; i++) { if (await evaluate(expression)) return; await sleep(50); } assert.fail(expression); };
    const button = (id, name) => `document.querySelector('#${id} .streams-${name}-toggle')`;
    const geometry = id => evaluate(`Array.from(document.querySelector('#${id} .streams-view-controls').children,e=>{const r=e.getBoundingClientRect();return {x:r.x,y:r.y,width:r.width,height:r.height}})`);
    await call('Runtime.enable');
    await wait("!!document.querySelector('#dashboard .streams-rank-target-toggle')");
    for (const width of [1400, 480, 360, 280]) {
      await call('Emulation.setDeviceMetricsOverride', { width, height: 600, deviceScaleFactor: 1, mobile: false });
      for (const id of ['tab', 'standalone', 'dashboard']) {
        await evaluate(`setups.${id}({mode:'tree',target:'flows',order:'tree'})`);
        await wait(`states.${id}.mode==='tree'&&${button(id, 'rank-target')}.disabled`);
        const before = await geometry(id);
        assert.ok(Math.abs(before[0].width-before[1].width)<.02, 'Mode/target toggles must have equal widths');
        assert.equal(await evaluate(`${button(id, 'view-mode')}.textContent`), 'Tree');
        assert.equal(await evaluate(`${button(id, 'rank-target')}.textContent`), 'Flows');
        await evaluate(`${button(id, 'rank-target')}.click()`);
        assert.equal(await evaluate(`states.${id}.target`), 'flows');
        await evaluate(`${button(id, 'view-mode')}.focus()`);
        await call('Input.dispatchKeyEvent', { type: 'keyDown', key: 'Enter', code: 'Enter', windowsVirtualKeyCode: 13, text: '\r' });
        await call('Input.dispatchKeyEvent', { type: 'keyUp', key: 'Enter', code: 'Enter', windowsVirtualKeyCode: 13 });
        await wait(`states.${id}.mode==='ranked'&&!${button(id, 'rank-target')}.disabled`);
        assert.equal(await evaluate(`states.${id}.order`), 'bitrate-desc');
        assert.equal(await evaluate(`${button(id, 'view-mode')}.textContent`), 'Ranked');
        assert.ok(await evaluate(`document.activeElement===${button(id, 'view-mode')}`), 'The mode button must retain keyboard focus');
        assert.deepEqual(await geometry(id), before, `${id}/${width}: switching mode must not move controls`);
        assert.ok(await evaluate(`${button(id, 'view-mode')}.querySelector('svg').classList.contains('lucide-list-ordered')`));
        await evaluate(`${button(id, 'rank-target')}.click()`); await wait(`states.${id}.target==='streams'`);
        assert.ok(await evaluate(`${button(id, 'rank-target')}.querySelector('svg').classList.contains('lucide-layout-list')`));
        assert.deepEqual(await geometry(id), before, `${id}/${width}: switching target must not move controls`);
        await evaluate(`setups.${id}({order:'alerts-desc'})`); await wait(`states.${id}.order==='alerts-desc'`);
        await evaluate(`${button(id, 'view-mode')}.click()`); await wait(`states.${id}.mode==='tree'`);
        assert.deepEqual(await evaluate(`states.${id}`), { mode: 'tree', target: 'streams', order: 'alerts-desc' });
        await evaluate(`${button(id, 'view-mode')}.click()`); await wait(`states.${id}.mode==='ranked'`);
        assert.deepEqual(await evaluate(`states.${id}`), { mode: 'ranked', target: 'streams', order: 'alerts-desc' });
        assert.deepEqual(await geometry(id), before);
        if (id === 'dashboard') {
          await evaluate(`(()=>{const select=document.querySelector('#dashboard select');select.value='last-seen-desc';select.dispatchEvent(new Event('change',{bubbles:true}))})()`);
        } else {
          await evaluate(`document.querySelector('#${id} .sort-control').click()`);
        }
        await wait(`states.${id}.order==='last-seen-desc'`);
        assert.deepEqual(await geometry(id), before, 'Sorting must not move the controls');
        assert.ok(await evaluate(`(()=>{const group=document.querySelector('#${id} .streams-view-controls'),outer=document.querySelector('#${id}');return group.scrollWidth===group.clientWidth&&group.getBoundingClientRect().right<=outer.getBoundingClientRect().right})()`), `${id}/${width}: controls must fit`);
      }
    }
    await evaluate("changeLocale('ja');setups.tab({mode:'tree'})");
    await wait(`${button('tab', 'view-mode')}.getAttribute('aria-label').includes('Ranked表示へ切り替え')`);
    assert.ok(await evaluate(`${button('tab', 'rank-target')}.getAttribute('aria-label').includes('Ranked表示でのみ変更')`));
    await evaluate(`${button('tab', 'view-mode')}.blur();${button('tab', 'view-mode')}.focus()`);
    await wait("document.querySelector('[role=tooltip]')?.textContent==='Ranked表示へ切り替え'");
    await evaluate("changeLocale('en')");
    await wait(`${button('tab', 'view-mode')}.getAttribute('aria-label')==='Tree: Switch to Ranked view'`);
    assert.deepEqual(errors, []);
  } finally {
    socket?.close(); chrome.kill('SIGTERM'); await new Promise(resolve => server.close(resolve));
  }
});
